def _validate_and_copy(col, converters):
    """Validate the format for the type converters and then copy those
    which are valid converters for this column (i.e. converter type is
    a subclass of col.type)"""
    # Allow specifying a single converter instead of a list of converters.
    # The input `converters` must be a ``type`` value that can init np.dtype.
    try:
        # Don't allow list-like things that dtype accepts
        assert type(converters) is type
        converters = [numpy.dtype(converters)]
    except (AssertionError, TypeError):
        pass

    converters_out = []
    try:
        for converter in converters:
            try:
                converter_func, converter_type = converter
            except TypeError as err:
                if str(err).startswith("cannot unpack"):
                    converter_func, converter_type = convert_numpy(converter)
                else:
                    raise
            if not issubclass(converter_type, NoType):
                raise ValueError("converter_type must be a subclass of NoType")
            if issubclass(converter_type, col.type):
                converters_out.append((converter_func, converter_type))

    except (ValueError, TypeError) as err:
        raise ValueError(
            "Error: invalid format for converters, see "
            f"documentation\n{converters}: {err}"
        )
    return converters_out

def _convert_vals(self, cols):
    for col in cols:
        for key, converters in self.converters.items():
            if fnmatch.fnmatch(col.name, key):
                break
        else:
            if col.dtype is not None:
                converters = [convert_numpy(col.dtype)]
            else:
                converters = self.default_converters

        col.converters = self._validate_and_copy(col, converters)

        # Catch the last error in order to provide additional information
        # in case all attempts at column conversion fail.  The initial
        # value of of last_error will apply if no converters are defined
        # and the first col.converters[0] access raises IndexError.
        last_err = "no converters defined"

        while not hasattr(col, "data"):
            # Try converters, popping the unsuccessful ones from the list.
            # If there are no converters left here then fail.
            if not col.converters:
                raise ValueError(f"Column {col.name} failed to convert: {last_err}")

            converter_func, converter_type = col.converters[0]
            if not issubclass(converter_type, col.type):
                raise TypeError("converter type does not match column type")

            try:
                col.data = converter_func(col.str_vals)
                col.type = converter_type
            except (OverflowError, TypeError, ValueError) as err:
                # Overflow during conversion (most likely an int that
                # doesn't fit in native C long). Put string at the top of
                # the converters list for the next while iteration.
                # With python/cpython#95778 this has been supplemented with a
                # "ValueError: Exceeds the limit (4300) for integer string conversion"
                # so need to catch that as well.
                if isinstance(err, OverflowError) or (
                    isinstance(err, ValueError)
                    and str(err).startswith("Exceeds the limit")
                ):
                    warnings.warn(
                        f"OverflowError converting to {converter_type.__name__} in"
                        f" column {col.name}, reverting to String.",
                        AstropyWarning,
                    )
                    col.converters.insert(0, convert_numpy(str))
                else:
                    col.converters.pop(0)
                last_err = err

def write_header(self, lines, meta):
    self.header.write_comments(lines, meta)
    self.header.write(lines)

def write_comments(self, lines, meta):
    if self.write_comment not in (False, None):
        for comment in meta.get("comments", []):
            lines.append(self.write_comment + comment)

def write(self, lines):
    if self.start_line is not None:
        for i, spacer_line in zip(
            range(self.start_line), itertools.cycle(self.write_spacer_lines)
        ):
            lines.append(spacer_line)
        lines.append(self.splitter.join([x.info.name for x in self.cols]))

def __init__(self, connection, collect_sql=False, atomic=True):
    self.connection = connection
    self.collect_sql = collect_sql
    if self.collect_sql:
        self.collected_sql = []
    self.atomic_migration = self.connection.features.can_rollback_ddl and atomic

def schema_editor(self, *args, **kwargs):
    """
    Return a new instance of this backend's SchemaEditor.
    """
    if self.SchemaEditorClass is None:
        raise NotImplementedError(
            'The SchemaEditorClass attribute of this database wrapper is still None')
    return self.SchemaEditorClass(self, *args, **kwargs)

def get_traceback_data(self):
    """Return a dictionary containing traceback information."""
    if self.exc_type and issubclass(self.exc_type, TemplateDoesNotExist):
        self.template_does_not_exist = True
        self.postmortem = self.exc_value.chain or [self.exc_value]

    frames = self.get_traceback_frames()
    for i, frame in enumerate(frames):
        if 'vars' in frame:
            frame_vars = []
            for k, v in frame['vars']:
                v = pprint(v)
                # Trim large blobs of data
                if len(v) > 4096:
                    v = '%s… <trimmed %d bytes string>' % (v[0:4096], len(v))
                frame_vars.append((k, v))
            frame['vars'] = frame_vars
        frames[i] = frame

    unicode_hint = ''
    if self.exc_type and issubclass(self.exc_type, UnicodeError):
        start = getattr(self.exc_value, 'start', None)
        end = getattr(self.exc_value, 'end', None)
        if start is not None and end is not None:
            unicode_str = self.exc_value.args[1]
            unicode_hint = force_str(
                unicode_str[max(start - 5, 0):min(end + 5, len(unicode_str))],
                'ascii', errors='replace'
            )
    from django import get_version

    if self.request is None:
        user_str = None
    else:
        try:
            user_str = str(self.request.user)
        except Exception:
            # request.user may raise OperationalError if the database is
            # unavailable, for example.
            user_str = '[unable to retrieve the current user]'

    c = {
        'is_email': self.is_email,
        'unicode_hint': unicode_hint,
        'frames': frames,
        'request': self.request,
        'user_str': user_str,
        'filtered_POST_items': list(self.filter.get_post_parameters(self.request).items()),
        'settings': get_safe_settings(),
        'sys_executable': sys.executable,
        'sys_version_info': '%d.%d.%d' % sys.version_info[0:3],
        'server_time': timezone.now(),
        'django_version_info': get_version(),
        'sys_path': sys.path,
        'template_info': self.template_info,
        'template_does_not_exist': self.template_does_not_exist,
        'postmortem': self.postmortem,
    }
    if self.request is not None:
        c['request_GET_items'] = self.request.GET.items()
        c['request_FILES_items'] = self.request.FILES.items()
        c['request_COOKIES_items'] = self.request.COOKIES.items()
    # Check whether exception info is available
    if self.exc_type:
        c['exception_type'] = self.exc_type.__name__
    if self.exc_value:
        c['exception_value'] = str(self.exc_value)
    if frames:
        c['lastframe'] = frames[-1]
    return c

def get_traceback_html(self):
    """Return HTML version of debug 500 HTTP error page."""
    with Path(CURRENT_DIR, 'templates', 'technical_500.html').open(encoding='utf-8') as fh:
        t = DEBUG_ENGINE.from_string(fh.read())
    c = Context(self.get_traceback_data(), use_l10n=False)
    return t.render(c)

def get_traceback_text(self):
    """Return plain text version of debug 500 HTTP error page."""
    with Path(CURRENT_DIR, 'templates', 'technical_500.txt').open(encoding='utf-8') as fh:
        t = DEBUG_ENGINE.from_string(fh.read())
    c = Context(self.get_traceback_data(), autoescape=False, use_l10n=False)
    return t.render(c)

def response_for_exception(request, exc):
    if isinstance(exc, Http404):
        if settings.DEBUG:
            response = debug.technical_404_response(request, exc)
        else:
            response = get_exception_response(request, get_resolver(get_urlconf()), 404, exc)

    elif isinstance(exc, PermissionDenied):
        response = get_exception_response(request, get_resolver(get_urlconf()), 403, exc)
        log_response(
            'Forbidden (Permission denied): %s', request.path,
            response=response,
            request=request,
            exc_info=sys.exc_info(),
        )

    elif isinstance(exc, MultiPartParserError):
        response = get_exception_response(request, get_resolver(get_urlconf()), 400, exc)
        log_response(
            'Bad request (Unable to parse request body): %s', request.path,
            response=response,
            request=request,
            exc_info=sys.exc_info(),
        )

    elif isinstance(exc, SuspiciousOperation):
        if isinstance(exc, (RequestDataTooBig, TooManyFieldsSent)):
            # POST data can't be accessed again, otherwise the original
            # exception would be raised.
            request._mark_post_parse_error()

        # The request logger receives events for any problematic request
        # The security logger receives events for all SuspiciousOperations
        security_logger = logging.getLogger('django.security.%s' % exc.__class__.__name__)
        security_logger.error(
            str(exc),
            extra={'status_code': 400, 'request': request},
        )
        if settings.DEBUG:
            response = debug.technical_500_response(request, *sys.exc_info(), status_code=400)
        else:
            response = get_exception_response(request, get_resolver(get_urlconf()), 400, exc)

    elif isinstance(exc, SystemExit):
        # Allow sys.exit() to actually exit. See tickets #1023 and #4701
        raise

    else:
        signals.got_request_exception.send(sender=None, request=request)
        response = handle_uncaught_exception(request, get_resolver(get_urlconf()), sys.exc_info())
        log_response(
            '%s: %s', response.reason_phrase, request.path,
            response=response,
            request=request,
            exc_info=sys.exc_info(),
        )

    # Force a TemplateResponse to be rendered.
    if not getattr(response, 'is_rendered', True) and callable(getattr(response, 'render', None)):
        response = response.render()

    return response

def technical_404_response(request, exception):
    """Create a technical 404 error response. `exception` is the Http404."""
    try:
        error_url = exception.args[0]['path']
    except (IndexError, TypeError, KeyError):
        error_url = request.path_info[1:]  # Trim leading slash

    try:
        tried = exception.args[0]['tried']
    except (IndexError, TypeError, KeyError):
        tried = []
    else:
        if (not tried or (                  # empty URLconf
            request.path == '/' and
            len(tried) == 1 and             # default URLconf
            len(tried[0]) == 1 and
            getattr(tried[0][0], 'app_name', '') == getattr(tried[0][0], 'namespace', '') == 'admin'
        )):
            return default_urlconf(request)

    urlconf = getattr(request, 'urlconf', settings.ROOT_URLCONF)
    if isinstance(urlconf, types.ModuleType):
        urlconf = urlconf.__name__

    caller = ''
    try:
        resolver_match = resolve(request.path)
    except Resolver404:
        pass
    else:
        obj = resolver_match.func

        if hasattr(obj, '__name__'):
            caller = obj.__name__
        elif hasattr(obj, '__class__') and hasattr(obj.__class__, '__name__'):
            caller = obj.__class__.__name__

        if hasattr(obj, '__module__'):
            module = obj.__module__
            caller = '%s.%s' % (module, caller)

    with Path(CURRENT_DIR, 'templates', 'technical_404.html').open(encoding='utf-8') as fh:
        t = DEBUG_ENGINE.from_string(fh.read())
    c = Context({
        'urlconf': urlconf,
        'root_urlconf': settings.ROOT_URLCONF,
        'request_path': error_url,
        'urlpatterns': tried,
        'reason': str(exception),
        'request': request,
        'settings': get_safe_settings(),
        'raising_view_name': caller,
    })
    return HttpResponseNotFound(t.render(c), content_type='text/html')

def get_exception_response(request, resolver, status_code, exception):
    try:
        callback, param_dict = resolver.resolve_error_handler(status_code)
        response = callback(request, **{**param_dict, 'exception': exception})
    except Exception:
        signals.got_request_exception.send(sender=None, request=request)
        response = handle_uncaught_exception(request, resolver, sys.exc_info())

    return response

def resolve_error_handler(self, view_type):
    callback = getattr(self.urlconf_module, 'handler%s' % view_type, None)
    if not callback:
        # No handler specified in file; use lazy import, since
        # django.conf.urls imports this file.
        from django.conf import urls
        callback = getattr(urls, 'handler%s' % view_type)
    return get_callable(callback), {}

def handle_uncaught_exception(request, resolver, exc_info):
    """
    Processing for any otherwise uncaught exceptions (those that will
    generate HTTP 500 responses).
    """
    if settings.DEBUG_PROPAGATE_EXCEPTIONS:
        raise

    if settings.DEBUG:
        return debug.technical_500_response(request, *exc_info)

    # Return an HttpResponse that displays a friendly error message.
    callback, param_dict = resolver.resolve_error_handler(500)
    return callback(request, **param_dict)

def display_for_value(value, empty_value_display, boolean=False):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon

    if boolean:
        return _boolean_icon(value)
    elif value is None:
        return empty_value_display
    elif isinstance(value, bool):
        return str(value)
    elif isinstance(value, datetime.datetime):
        return formats.localize(timezone.template_localtime(value))
    elif isinstance(value, (datetime.date, datetime.time)):
        return formats.localize(value)
    elif isinstance(value, (int, decimal.Decimal, float)):
        return formats.number_format(value)
    elif isinstance(value, (list, tuple)):
        return ', '.join(str(v) for v in value)
    else:
        return str(value)

def lookup_field(name, obj, model_admin=None):
    opts = obj._meta
    try:
        f = _get_non_gfk_field(opts, name)
    except (FieldDoesNotExist, FieldIsAForeignKeyColumnName):
        # For non-field values, the value is either a method, property or
        # returned via a callable.
        if callable(name):
            attr = name
            value = attr(obj)
        elif hasattr(model_admin, name) and name != '__str__':
            attr = getattr(model_admin, name)
            value = attr(obj)
        else:
            attr = getattr(obj, name)
            if callable(attr):
                value = attr()
            else:
                value = attr
        f = None
    else:
        attr = None
        value = getattr(obj, name)
    return f, attr, value

def contents(self):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon
    field, obj, model_admin = self.field['field'], self.form.instance, self.model_admin
    try:
        f, attr, value = lookup_field(field, obj, model_admin)
    except (AttributeError, ValueError, ObjectDoesNotExist):
        result_repr = self.empty_value_display
    else:
        if field in self.form.fields:
            widget = self.form[field].field.widget
            # This isn't elegant but suffices for contrib.auth's
            # ReadOnlyPasswordHashWidget.
            if getattr(widget, 'read_only', False):
                return widget.render(field, value)
        if f is None:
            if getattr(attr, 'boolean', False):
                result_repr = _boolean_icon(value)
            else:
                if hasattr(value, "__html__"):
                    result_repr = value
                else:
                    result_repr = linebreaksbr(value)
        else:
            if isinstance(f.remote_field, ManyToManyRel) and value is not None:
                result_repr = ", ".join(map(str, value.all()))
            else:
                result_repr = display_for_field(value, f, self.empty_value_display)
            result_repr = linebreaksbr(result_repr)
    return conditional_escape(result_repr)

def label_for_field(name, model, model_admin=None, return_attr=False, form=None):
    """
    Return a sensible label for a field name. The name can be a callable,
    property (but not created with @property decorator), or the name of an
    object's attribute, as well as a model field. If return_attr is True, also
    return the resolved attribute (which could be a callable). This will be
    None if (and only if) the name refers to a field.
    """
    attr = None
    try:
        field = _get_non_gfk_field(model._meta, name)
        try:
            label = field.verbose_name
        except AttributeError:
            # field is likely a ForeignObjectRel
            label = field.related_model._meta.verbose_name
    except FieldDoesNotExist:
        if name == "__str__":
            label = str(model._meta.verbose_name)
            attr = str
        else:
            if callable(name):
                attr = name
            elif hasattr(model_admin, name):
                attr = getattr(model_admin, name)
            elif hasattr(model, name):
                attr = getattr(model, name)
            elif form and name in form.fields:
                attr = form.fields[name]
            else:
                message = "Unable to lookup '%s' on %s" % (name, model._meta.object_name)
                if model_admin:
                    message += " or %s" % model_admin.__class__.__name__
                if form:
                    message += " or %s" % form.__class__.__name__
                raise AttributeError(message)

            if hasattr(attr, "short_description"):
                label = attr.short_description
            elif (isinstance(attr, property) and
                  hasattr(attr, "fget") and
                  hasattr(attr.fget, "short_description")):
                label = attr.fget.short_description
            elif callable(attr):
                if attr.__name__ == "<lambda>":
                    label = "--"
                else:
                    label = pretty_name(attr.__name__)
            else:
                label = pretty_name(name)
    except FieldIsAForeignKeyColumnName:
        label = pretty_name(name)
        attr = name

    if return_attr:
        return (label, attr)
    else:
        return label

def label_tag(self):
    attrs = {}
    if not self.is_first:
        attrs["class"] = "inline"
    label = self.field['label']
    return format_html('<label{}>{}{}</label>', flatatt(attrs), capfirst(label), self.form.label_suffix)

def help_text_for_field(name, model):
    help_text = ""
    try:
        field = _get_non_gfk_field(model._meta, name)
    except (FieldDoesNotExist, FieldIsAForeignKeyColumnName):
        pass
    else:
        if hasattr(field, 'help_text'):
            help_text = field.help_text
    return help_text

def alter_index_together(self, model, old_index_together, new_index_together):
    """
    Deal with a model changing its index_together. The input
    index_togethers must be doubly-nested, not the single-nested
    ["foo", "bar"] format.
    """
    olds = {tuple(fields) for fields in old_index_together}
    news = {tuple(fields) for fields in new_index_together}
    # Deleted indexes
    for fields in olds.difference(news):
        self._delete_composed_index(model, fields, {'index': True}, self.sql_delete_index)
    # Created indexes
    for field_names in news.difference(olds):
        fields = [model._meta.get_field(field) for field in field_names]
        self.execute(self._create_index_sql(model, fields, suffix="_idx"))

def alter_unique_together(self, model, old_unique_together, new_unique_together):
    """
    Deal with a model changing its unique_together. The input
    unique_togethers must be doubly-nested, not the single-nested
    ["foo", "bar"] format.
    """
    olds = {tuple(fields) for fields in old_unique_together}
    news = {tuple(fields) for fields in new_unique_together}
    # Deleted uniques
    for fields in olds.difference(news):
        self._delete_composed_index(model, fields, {'unique': True}, self.sql_delete_unique)
    # Created uniques
    for fields in news.difference(olds):
        columns = [model._meta.get_field(field).column for field in fields]
        self.execute(self._create_unique_sql(model, columns))

def _delete_index_sql(self, model, name, sql=None):
    return Statement(
        sql or self.sql_delete_index,
        table=Table(model._meta.db_table, self.quote_name),
        name=self.quote_name(name),
    )

def database_forwards(self, app_label, schema_editor, from_state, to_state):
    to_model = to_state.apps.get_model(app_label, self.name)
    if self.allow_migrate_model(schema_editor.connection.alias, to_model):
        from_model = from_state.apps.get_model(app_label, self.name)
        # Remove a field if we need to
        if from_model._meta.order_with_respect_to and not to_model._meta.order_with_respect_to:
            schema_editor.remove_field(from_model, from_model._meta.get_field("_order"))
        # Add a field if we need to (altering the column is untouched as
        # it's likely a rename)
        elif to_model._meta.order_with_respect_to and not from_model._meta.order_with_respect_to:
            field = to_model._meta.get_field("_order")
            if not field.has_default():
                field.default = 0
            schema_editor.add_field(
                from_model,
                field,
            )

def database_forwards(self, app_label, schema_editor, from_state, to_state):
    model = to_state.apps.get_model(app_label, self.model_name)
    if self.allow_migrate_model(schema_editor.connection.alias, model):
        schema_editor.add_index(model, self.index)

def add_field(self, model, field):
    """
    Create a field on a model. Usually involves adding a column, but may
    involve adding a table instead (for M2M fields).
    """
    # Special-case implicit M2M tables
    if field.many_to_many and field.remote_field.through._meta.auto_created:
        return self.create_model(field.remote_field.through)
    # Get the column's definition
    definition, params = self.column_sql(model, field, include_default=True)
    # It might not actually have a column behind it
    if definition is None:
        return
    # Check constraints can go on the column SQL here
    db_params = field.db_parameters(connection=self.connection)
    if db_params['check']:
        definition += " " + self.sql_check_constraint % db_params
    if field.remote_field and self.connection.features.supports_foreign_keys and field.db_constraint:
        constraint_suffix = '_fk_%(to_table)s_%(to_column)s'
        # Add FK constraint inline, if supported.
        if self.sql_create_column_inline_fk:
            to_table = field.remote_field.model._meta.db_table
            to_column = field.remote_field.model._meta.get_field(field.remote_field.field_name).column
            namespace, _ = split_identifier(model._meta.db_table)
            definition += " " + self.sql_create_column_inline_fk % {
                'name': self._fk_constraint_name(model, field, constraint_suffix),
                'namespace': '%s.' % self.quote_name(namespace) if namespace else '',
                'column': self.quote_name(field.column),
                'to_table': self.quote_name(to_table),
                'to_column': self.quote_name(to_column),
                'deferrable': self.connection.ops.deferrable_sql()
            }
        # Otherwise, add FK constraints later.
        else:
            self.deferred_sql.append(self._create_fk_sql(model, field, constraint_suffix))
    # Build the SQL and run it
    sql = self.sql_create_column % {
        "table": self.quote_name(model._meta.db_table),
        "column": self.quote_name(field.column),
        "definition": definition,
    }
    self.execute(sql, params)
    # Drop the default if we need to
    # (Django usually does not use in-database defaults)
    if not self.skip_default(field) and self.effective_default(field) is not None:
        changes_sql, params = self._alter_column_default_sql(model, None, field, drop=True)
        sql = self.sql_alter_column % {
            "table": self.quote_name(model._meta.db_table),
            "changes": changes_sql,
        }
        self.execute(sql, params)
    # Add an index, if required
    self.deferred_sql.extend(self._field_indexes_sql(model, field))
    # Reset connection if required
    if self.connection.features.connection_persists_old_columns:
        self.connection.close()

def _prepare_field_lists(self):
    """
    Prepare field lists and a list of the fields that used through models
    in the old state so dependencies can be made from the through model
    deletion to the field that uses it.
    """
    self.kept_model_keys = self.old_model_keys & self.new_model_keys
    self.kept_proxy_keys = self.old_proxy_keys & self.new_proxy_keys
    self.kept_unmanaged_keys = self.old_unmanaged_keys & self.new_unmanaged_keys
    self.through_users = {}
    self.old_field_keys = {
        (app_label, model_name, field_name)
        for app_label, model_name in self.kept_model_keys
        for field_name in self.from_state.models[
            app_label,
            self.renamed_models.get((app_label, model_name), model_name)
        ].fields
    }
    self.new_field_keys = {
        (app_label, model_name, field_name)
        for app_label, model_name in self.kept_model_keys
        for field_name in self.to_state.models[app_label, model_name].fields
    }

def form_valid(self, form):
    opts = {
        'use_https': self.request.is_secure(),
        'token_generator': self.token_generator,
        'from_email': self.from_email,
        'email_template_name': self.email_template_name,
        'subject_template_name': self.subject_template_name,
        'request': self.request,
        'html_email_template_name': self.html_email_template_name,
        'extra_email_context': self.extra_email_context,
    }
    form.save(**opts)
    return super().form_valid(form)

def form_valid(self, form):
    user = form.save()
    del self.request.session[INTERNAL_RESET_SESSION_TOKEN]
    if self.post_reset_login:
        auth_login(self.request, user, self.post_reset_login_backend)
    return super().form_valid(form)

def check_token(self, user, token):
    """
    Check that a password reset token is correct for a given user.
    """
    if not (user and token):
        return False
    # Parse the token
    try:
        ts_b36, _ = token.split("-")
    except ValueError:
        return False

    try:
        ts = base36_to_int(ts_b36)
    except ValueError:
        return False

    # Check that the timestamp/uid has not been tampered with
    if not constant_time_compare(self._make_token_with_timestamp(user, ts), token):
        # RemovedInDjango40Warning: when the deprecation ends, replace
        # with:
        #   return False
        if not constant_time_compare(
            self._make_token_with_timestamp(user, ts, legacy=True),
            token,
        ):
            return False

    # Check the timestamp is within limit.
    if (self._num_seconds(self._now()) - ts) > settings.PASSWORD_RESET_TIMEOUT:
        return False

    return True

def get_connection_params(self):
    conn_params = self.settings_dict['OPTIONS'].copy()
    if 'use_returning_into' in conn_params:
        del conn_params['use_returning_into']
    return conn_params

def compile_json_path(key_transforms, include_root=True):
    path = ['$'] if include_root else []
    for key_transform in key_transforms:
        try:
            num = int(key_transform)
        except ValueError:  # non-integer
            path.append('.')
            path.append(json.dumps(key_transform))
        else:
            path.append('[%s]' % num)
    return ''.join(path)

def as_sql(self, compiler, connection, template=None):
    # Process JSON path from the left-hand side.
    if isinstance(self.lhs, KeyTransform):
        lhs, lhs_params, lhs_key_transforms = self.lhs.preprocess_lhs(compiler, connection)
        lhs_json_path = compile_json_path(lhs_key_transforms)
    else:
        lhs, lhs_params = self.process_lhs(compiler, connection)
        lhs_json_path = '$'
    sql = template % lhs
    # Process JSON path from the right-hand side.
    rhs = self.rhs
    rhs_params = []
    if not isinstance(rhs, (list, tuple)):
        rhs = [rhs]
    for key in rhs:
        if isinstance(key, KeyTransform):
            *_, rhs_key_transforms = key.preprocess_lhs(compiler, connection)
        else:
            rhs_key_transforms = [key]
        rhs_params.append('%s%s' % (
            lhs_json_path,
            compile_json_path(rhs_key_transforms, include_root=False),
        ))
    # Add condition for each key.
    if self.logical_operator:
        sql = '(%s)' % self.logical_operator.join([sql] * len(rhs_params))
    return sql, tuple(lhs_params) + tuple(rhs_params)

def as_mysql(self, compiler, connection):
    lhs, params, key_transforms = self.preprocess_lhs(compiler, connection)
    json_path = compile_json_path(key_transforms)
    return 'JSON_EXTRACT(%s, %%s)' % lhs, tuple(params) + (json_path,)

def as_postgresql(self, compiler, connection):
    lhs, params, key_transforms = self.preprocess_lhs(compiler, connection)
    if len(key_transforms) > 1:
        sql = '(%s %s %%s)' % (lhs, self.postgres_nested_operator)
        return sql, tuple(params) + (key_transforms,)
    try:
        lookup = int(self.key_name)
    except ValueError:
        lookup = self.key_name
    return '(%s %s %%s)' % (lhs, self.postgres_operator), tuple(params) + (lookup,)

def validate_name(self, name, name_or_dir='name'):
    if name is None:
        raise CommandError('you must provide {an} {app} name'.format(
            an=self.a_or_an,
            app=self.app_or_project,
        ))
    # Check it's a valid directory name.
    if not name.isidentifier():
        raise CommandError(
            "'{name}' is not a valid {app} {type}. Please make sure the "
            "{type} is a valid identifier.".format(
                name=name,
                app=self.app_or_project,
                type=name_or_dir,
            )
        )
    # Check it cannot be imported.
    try:
        import_module(name)
    except ImportError:
        pass
    else:
        raise CommandError(
            "'{name}' conflicts with the name of an existing Python "
            "module and cannot be used as {an} {app} {type}. Please try "
            "another {type}.".format(
                name=name,
                an=self.a_or_an,
                app=self.app_or_project,
                type=name_or_dir,
            )
        )

def handle_template(self, template, subdir):
    """
    Determine where the app or project templates are.
    Use django.__path__[0] as the default because the Django install
    directory isn't known.
    """
    if template is None:
        return os.path.join(django.__path__[0], 'conf', subdir)
    else:
        if template.startswith('file://'):
            template = template[7:]
        expanded_template = os.path.expanduser(template)
        expanded_template = os.path.normpath(expanded_template)
        if os.path.isdir(expanded_template):
            return expanded_template
        if self.is_url(template):
            # downloads the file and returns the path
            absolute_path = self.download(template)
        else:
            absolute_path = os.path.abspath(expanded_template)
        if os.path.exists(absolute_path):
            return self.extract(absolute_path)

    raise CommandError("couldn't handle %s template %s." %
                       (self.app_or_project, template))

def get_urls(self):
    from django.urls import path

    def wrap(view):
        def wrapper(*args, **kwargs):
            return self.admin_site.admin_view(view)(*args, **kwargs)
        wrapper.model_admin = self
        return update_wrapper(wrapper, view)

    info = self.model._meta.app_label, self.model._meta.model_name

    return [
        path('', wrap(self.changelist_view), name='%s_%s_changelist' % info),
        path('add/', wrap(self.add_view), name='%s_%s_add' % info),
        path('<path:object_id>/history/', wrap(self.history_view), name='%s_%s_history' % info),
        path('<path:object_id>/delete/', wrap(self.delete_view), name='%s_%s_delete' % info),
        path('<path:object_id>/change/', wrap(self.change_view), name='%s_%s_change' % info),
        # For backwards compatibility (was the change url before 1.9)
        path('<path:object_id>/', wrap(RedirectView.as_view(
            pattern_name='%s:%s_%s_change' % ((self.admin_site.name,) + info)
        ))),
    ]

def get_paginator(self, *args, **kwargs):
    """Use the ModelAdmin's paginator."""
    return self.model_admin.get_paginator(self.request, *args, **kwargs)

def process_request(self, request):
    """
    Validate request integrity, extract and return request parameters.

    Since the subsequent view permission check requires the target model
    admin, which is determined here, raise PermissionDenied if the
    requested app, model or field are malformed.

    Raise Http404 if the target model admin is not configured properly with
    search_fields.
    """
    term = request.GET.get('term', '')
    try:
        app_label = request.GET['app_label']
        model_name = request.GET['model_name']
        field_name = request.GET['field_name']
    except KeyError as e:
        raise PermissionDenied from e

    # Retrieve objects from parameters.
    try:
        source_model = apps.get_model(app_label, model_name)
    except LookupError as e:
        raise PermissionDenied from e

    try:
        source_field = source_model._meta.get_field(field_name)
    except FieldDoesNotExist as e:
        raise PermissionDenied from e
    try:
        remote_model = source_field.remote_field.model
    except AttributeError as e:
        raise PermissionDenied from e
    try:
        model_admin = self.admin_site._registry[remote_model]
    except KeyError as e:
        raise PermissionDenied from e

    # Validate suitability of objects.
    if not model_admin.get_search_fields(request):
        raise Http404(
            '%s must have search_fields for the autocomplete_view.' %
            type(model_admin).__qualname__
        )

    to_field_name = getattr(source_field.remote_field, 'field_name', remote_model._meta.pk.attname)
    to_field_name = remote_model._meta.get_field(to_field_name).attname
    if not model_admin.to_field_allowed(request, to_field_name):
        raise PermissionDenied

    return term, model_admin, source_field, to_field_name

def has_perm(self, request, obj=None):
    """Check if user has permission to access the related model."""
    return self.model_admin.has_view_permission(request, obj=obj)

def get_context(self, name, value, attrs):
    context = super().get_context(name, value, attrs)
    rel_to = self.rel.model
    if rel_to in self.admin_site._registry:
        # The related object is registered with the same AdminSite
        related_url = reverse(
            'admin:%s_%s_changelist' % (
                rel_to._meta.app_label,
                rel_to._meta.model_name,
            ),
            current_app=self.admin_site.name,
        )

        params = self.url_parameters()
        if params:
            related_url += '?' + urlencode(params)
        context['related_url'] = related_url
        context['link_title'] = _('Lookup')
        # The JavaScript code looks for this class.
        context['widget']['attrs'].setdefault('class', 'vForeignKeyRawIdAdminField')
    else:
        context['related_url'] = None
    if context['widget']['value']:
        context['link_label'], context['link_url'] = self.label_and_url_for_value(value)
    else:
        context['link_label'] = None
    return context

def get_context(self, name, value, attrs):
    context = super().get_context(name, value, attrs)
    if self.rel.model in self.admin_site._registry:
        # The related object is registered with the same AdminSite
        context['widget']['attrs']['class'] = 'vManyToManyRawIdAdminField'
    return context

def __call__(self, value):
    if not isinstance(value, str):
        raise ValidationError(self.message, code=self.code, params={'value': value})
    if self.unsafe_chars.intersection(value):
        raise ValidationError(self.message, code=self.code, params={'value': value})
    # Check if the scheme is valid.
    scheme = value.split('://')[0].lower()
    if scheme not in self.schemes:
        raise ValidationError(self.message, code=self.code, params={'value': value})

    # Then check full URL
    try:
        super().__call__(value)
    except ValidationError as e:
        # Trivial case failed. Try for possible IDN domain
        if value:
            try:
                scheme, netloc, path, query, fragment = urlsplit(value)
            except ValueError:  # for example, "Invalid IPv6 URL"
                raise ValidationError(self.message, code=self.code, params={'value': value})
            try:
                netloc = punycode(netloc)  # IDN -> ACE
            except UnicodeError:  # invalid domain part
                raise e
            url = urlunsplit((scheme, netloc, path, query, fragment))
            super().__call__(url)
        else:
            raise
    else:
        # Now verify IPv6 in the netloc part
        host_match = re.search(r'^\[(.+)\](?::\d{1,5})?$', urlsplit(value).netloc)
        if host_match:
            potential_ip = host_match[1]
            try:
                validate_ipv6_address(potential_ip)
            except ValidationError:
                raise ValidationError(self.message, code=self.code, params={'value': value})

    # The maximum length of a full host name is 253 characters per RFC 1034
    # section 3.1. It's defined to be 255 bytes or less, but this includes
    # one byte for the length of the name and one byte for the trailing dot
    # that's used to indicate absolute names in DNS.
    if len(urlsplit(value).hostname) > 253:
        raise ValidationError(self.message, code=self.code, params={'value': value})

def clean_ipv6_address(ip_str, unpack_ipv4=False,
                       error_message=_("This is not a valid IPv6 address.")):
    """
    Clean an IPv6 address string.

    Raise ValidationError if the address is invalid.

    Replace the longest continuous zero-sequence with "::", remove leading
    zeroes, and make sure all hextets are lowercase.

    Args:
        ip_str: A valid IPv6 address.
        unpack_ipv4: if an IPv4-mapped address is found,
        return the plain IPv4 address (default=False).
        error_message: An error message used in the ValidationError.

    Return a compressed IPv6 address or the same value.
    """
    try:
        addr = ipaddress.IPv6Address(int(ipaddress.IPv6Address(ip_str)))
    except ValueError:
        raise ValidationError(error_message, code='invalid')

    if unpack_ipv4 and addr.ipv4_mapped:
        return str(addr.ipv4_mapped)
    elif addr.ipv4_mapped:
        return '::ffff:%s' % str(addr.ipv4_mapped)

    return str(addr)

def __init__(self, schemes=None, **kwargs):
    super().__init__(**kwargs)
    if schemes is not None:
        self.schemes = schemes

def __init__(self, message, code=None, params=None):
    """
    The `message` argument can be a single error, a list of errors, or a
    dictionary that maps field names to lists of errors. What we define as
    an "error" can be either a simple string or an instance of
    ValidationError with its message attribute set, and what we define as
    list or dictionary can be an actual `list` or `dict` or an instance
    of ValidationError with its `error_list` or `error_dict` attribute set.
    """
    super().__init__(message, code, params)

    if isinstance(message, ValidationError):
        if hasattr(message, 'error_dict'):
            message = message.error_dict
        elif not hasattr(message, 'message'):
            message = message.error_list
        else:
            message, code, params = message.message, message.code, message.params

    if isinstance(message, dict):
        self.error_dict = {}
        for field, messages in message.items():
            if not isinstance(messages, ValidationError):
                messages = ValidationError(messages)
            self.error_dict[field] = messages.error_list

    elif isinstance(message, list):
        self.error_list = []
        for message in message:
            # Normalize plain strings to instances of ValidationError.
            if not isinstance(message, ValidationError):
                message = ValidationError(message)
            if hasattr(message, 'error_dict'):
                self.error_list.extend(sum(message.error_dict.values(), []))
            else:
                self.error_list.extend(message.error_list)

    else:
        self.message = message
        self.code = code
        self.params = params
        self.error_list = [self]

def run_validators(self, value):
    if value in self.empty_values:
        return
    errors = []
    for v in self.validators:
        try:
            v(value)
        except ValidationError as e:
            if hasattr(e, 'code') and e.code in self.error_messages:
                e.message = self.error_messages[e.code]
            errors.extend(e.error_list)
    if errors:
        raise ValidationError(errors)

def get_field_type(self, connection, table_name, row):
    """
    Given the database connection, the table name, and the cursor row
    description, this routine will return the given field type name, as
    well as any additional keyword parameters and notes for the field.
    """
    field_params = {}
    field_notes = []

    try:
        field_type = connection.introspection.get_field_type(row.type_code, row)
    except KeyError:
        field_type = "TextField"
        field_notes.append("This field type is a guess.")

    # Add max_length for all CharFields.
    if field_type == "CharField" and row.internal_size:
        field_params["max_length"] = int(row.internal_size)

    if field_type in {"CharField", "TextField"} and row.collation:
        field_params["db_collation"] = row.collation

    if field_type == "DecimalField":
        if row.precision is None or row.scale is None:
            field_notes.append(
                "max_digits and decimal_places have been guessed, as this "
                "database handles decimal fields as float"
            )
            field_params["max_digits"] = (
                row.precision if row.precision is not None else 10
            )
            field_params["decimal_places"] = (
                row.scale if row.scale is not None else 5
            )
        else:
            field_params["max_digits"] = row.precision
            field_params["decimal_places"] = row.scale

    return field_type, field_params, field_notes

def get_meta(
    self, table_name, constraints, column_to_field_name, is_view, is_partition
):
    """
    Return a sequence comprising the lines of code necessary
    to construct the inner Meta class for the model corresponding
    to the given database table name.
    """
    unique_together = []
    has_unsupported_constraint = False
    for params in constraints.values():
        if params["unique"]:
            columns = params["columns"]
            if None in columns:
                has_unsupported_constraint = True
            columns = [
                x for x in columns if x is not None and x in column_to_field_name
            ]
            if len(columns) > 1:
                unique_together.append(
                    str(tuple(column_to_field_name[c] for c in columns))
                )
    if is_view:
        managed_comment = "  # Created from a view. Don't remove."
    elif is_partition:
        managed_comment = "  # Created from a partition. Don't remove."
    else:
        managed_comment = ""
    meta = [""]
    if has_unsupported_constraint:
        meta.append("    # A unique constraint could not be introspected.")
    meta += [
        "    class Meta:",
        "        managed = False%s" % managed_comment,
        "        db_table = %r" % table_name,
    ]
    if unique_together:
        tup = "(" + ", ".join(unique_together) + ",)"
        meta += ["        unique_together = %s" % tup]
    return meta

def contribute_to_class(self, cls, name, private_only=False, **kwargs):

    super().contribute_to_class(cls, name, private_only=private_only, **kwargs)

    self.opts = cls._meta

    if not cls._meta.abstract:
        if self.remote_field.related_name:
            related_name = self.remote_field.related_name
        else:
            related_name = self.opts.default_related_name
        if related_name:
            related_name = related_name % {
                "class": cls.__name__.lower(),
                "model_name": cls._meta.model_name.lower(),
                "app_label": cls._meta.app_label.lower(),
            }
            self.remote_field.related_name = related_name

        if self.remote_field.related_query_name:
            related_query_name = self.remote_field.related_query_name % {
                "class": cls.__name__.lower(),
                "app_label": cls._meta.app_label.lower(),
            }
            self.remote_field.related_query_name = related_query_name

        def resolve_related_class(model, related, field):
            field.remote_field.model = related
            field.do_related_class(related, model)

        lazy_related_operation(
            resolve_related_class, cls, self.remote_field.model, field=self
        )

def handle_inspection(self, options):
    connection = connections[options["database"]]
    # 'table_name_filter' is a stealth option
    table_name_filter = options.get("table_name_filter")

    def table2model(table_name):
        return re.sub(r"[^a-zA-Z0-9]", "", table_name.title())

    with connection.cursor() as cursor:
        yield "# This is an auto-generated Django model module."
        yield "# You'll have to do the following manually to clean this up:"
        yield "#   * Rearrange models' order"
        yield "#   * Make sure each model has one field with primary_key=True"
        yield (
            "#   * Make sure each ForeignKey and OneToOneField has `on_delete` set "
            "to the desired behavior"
        )
        yield (
            "#   * Remove `managed = False` lines if you wish to allow "
            "Django to create, modify, and delete the table"
        )
        yield (
            "# Feel free to rename the models, but don't rename db_table values or "
            "field names."
        )
        yield "from %s import models" % self.db_module
        known_models = []
        table_info = connection.introspection.get_table_list(cursor)

        # Determine types of tables and/or views to be introspected.
        types = {"t"}
        if options["include_partitions"]:
            types.add("p")
        if options["include_views"]:
            types.add("v")

        for table_name in options["table"] or sorted(
            info.name for info in table_info if info.type in types
        ):
            if table_name_filter is not None and callable(table_name_filter):
                if not table_name_filter(table_name):
                    continue
            try:
                try:
                    relations = connection.introspection.get_relations(
                        cursor, table_name
                    )
                except NotImplementedError:
                    relations = {}
                try:
                    constraints = connection.introspection.get_constraints(
                        cursor, table_name
                    )
                except NotImplementedError:
                    constraints = {}
                primary_key_columns = (
                    connection.introspection.get_primary_key_columns(
                        cursor, table_name
                    )
                )
                primary_key_column = (
                    primary_key_columns[0] if primary_key_columns else None
                )
                unique_columns = [
                    c["columns"][0]
                    for c in constraints.values()
                    if c["unique"] and len(c["columns"]) == 1
                ]
                table_description = connection.introspection.get_table_description(
                    cursor, table_name
                )
            except Exception as e:
                yield "# Unable to inspect table '%s'" % table_name
                yield "# The error was: %s" % e
                continue

            yield ""
            yield ""
            yield "class %s(models.Model):" % table2model(table_name)
            known_models.append(table2model(table_name))
            used_column_names = []  # Holds column names used in the table so far
            column_to_field_name = {}  # Maps column names to names of model fields
            for row in table_description:
                comment_notes = (
                    []
                )  # Holds Field notes, to be displayed in a Python comment.
                extra_params = {}  # Holds Field parameters such as 'db_column'.
                column_name = row.name
                is_relation = column_name in relations

                att_name, params, notes = self.normalize_col_name(
                    column_name, used_column_names, is_relation
                )
                extra_params.update(params)
                comment_notes.extend(notes)

                used_column_names.append(att_name)
                column_to_field_name[column_name] = att_name

                # Add primary_key and unique, if necessary.
                if column_name == primary_key_column:
                    extra_params["primary_key"] = True
                    if len(primary_key_columns) > 1:
                        comment_notes.append(
                            "The composite primary key (%s) found, that is not "
                            "supported. The first column is selected."
                            % ", ".join(primary_key_columns)
                        )
                elif column_name in unique_columns:
                    extra_params["unique"] = True

                if is_relation:
                    ref_db_column, ref_db_table = relations[column_name]
                    if extra_params.pop("unique", False) or extra_params.get(
                        "primary_key"
                    ):
                        rel_type = "OneToOneField"
                    else:
                        rel_type = "ForeignKey"
                        ref_pk_column = (
                            connection.introspection.get_primary_key_column(
                                cursor, ref_db_table
                            )
                        )
                        if ref_pk_column and ref_pk_column != ref_db_column:
                            extra_params["to_field"] = ref_db_column
                    rel_to = (
                        "self"
                        if ref_db_table == table_name
                        else table2model(ref_db_table)
                    )
                    if rel_to in known_models:
                        field_type = "%s(%s" % (rel_type, rel_to)
                    else:
                        field_type = "%s('%s'" % (rel_type, rel_to)
                else:
                    # Calling `get_field_type` to get the field type string and any
                    # additional parameters and notes.
                    field_type, field_params, field_notes = self.get_field_type(
                        connection, table_name, row
                    )
                    extra_params.update(field_params)
                    comment_notes.extend(field_notes)

                    field_type += "("

                # Don't output 'id = meta.AutoField(primary_key=True)', because
                # that's assumed if it doesn't exist.
                if att_name == "id" and extra_params == {"primary_key": True}:
                    if field_type == "AutoField(":
                        continue
                    elif (
                        field_type
                        == connection.features.introspected_field_types["AutoField"]
                        + "("
                    ):
                        comment_notes.append("AutoField?")

                # Add 'null' and 'blank', if the 'null_ok' flag was present in the
                # table description.
                if row.null_ok:  # If it's NULL...
                    extra_params["blank"] = True
                    extra_params["null"] = True

                field_desc = "%s = %s%s" % (
                    att_name,
                    # Custom fields will have a dotted path
                    "" if "." in field_type else "models.",
                    field_type,
                )
                if field_type.startswith(("ForeignKey(", "OneToOneField(")):
                    field_desc += ", models.DO_NOTHING"

                if extra_params:
                    if not field_desc.endswith("("):
                        field_desc += ", "
                    field_desc += ", ".join(
                        "%s=%r" % (k, v) for k, v in extra_params.items()
                    )
                field_desc += ")"
                if comment_notes:
                    field_desc += "  # " + " ".join(comment_notes)
                yield "    %s" % field_desc
            is_view = any(
                info.name == table_name and info.type == "v" for info in table_info
            )
            is_partition = any(
                info.name == table_name and info.type == "p" for info in table_info
            )
            yield from self.get_meta(
                table_name, constraints, column_to_field_name, is_view, is_partition
            )

