def get_latest_lastmod(self):
    if self.date_field is not None:
        return (
            self.queryset.order_by("-" + self.date_field)
            .values_list(self.date_field, flat=True)
            .first()
        )
    return None

def index(
    request,
    sitemaps,
    template_name="sitemap_index.xml",
    content_type="application/xml",
    sitemap_url_name="django.contrib.sitemaps.views.sitemap",
):

    req_protocol = request.scheme
    req_site = get_current_site(request)

    sites = []  # all sections' sitemap URLs
    all_indexes_lastmod = True
    latest_lastmod = None
    for section, site in sitemaps.items():
        # For each section label, add links of all pages of its sitemap
        # (usually generated by the `sitemap` view).
        if callable(site):
            site = site()
        protocol = req_protocol if site.protocol is None else site.protocol
        sitemap_url = reverse(sitemap_url_name, kwargs={"section": section})
        absolute_url = "%s://%s%s" % (protocol, req_site.domain, sitemap_url)
        site_lastmod = site.get_latest_lastmod()
        if all_indexes_lastmod:
            if site_lastmod is not None:
                latest_lastmod = _get_latest_lastmod(latest_lastmod, site_lastmod)
            else:
                all_indexes_lastmod = False
        sites.append(SitemapIndexItem(absolute_url, site_lastmod))
        # Add links to all pages of the sitemap.
        for page in range(2, site.paginator.num_pages + 1):
            sites.append(
                SitemapIndexItem("%s?p=%s" % (absolute_url, page), site_lastmod)
            )
    # If lastmod is defined for all sites, set header so as
    # ConditionalGetMiddleware is able to send 304 NOT MODIFIED
    if all_indexes_lastmod and latest_lastmod:
        headers = {"Last-Modified": http_date(latest_lastmod.timestamp())}
    else:
        headers = None
    return TemplateResponse(
        request,
        template_name,
        {"sitemaps": sites},
        content_type=content_type,
        headers=headers,
    )

def _get_latest_lastmod(current_lastmod, new_lastmod):
    """
    Returns the latest `lastmod` where `lastmod` can be either a date or a
    datetime.
    """
    if not isinstance(new_lastmod, datetime.datetime):
        new_lastmod = datetime.datetime.combine(new_lastmod, datetime.time.min)
    if timezone.is_naive(new_lastmod):
        new_lastmod = timezone.make_aware(new_lastmod, datetime.timezone.utc)
    return new_lastmod if current_lastmod is None else max(current_lastmod, new_lastmod)

def items(self):
    # Make sure to return a clone; we don't want premature evaluation.
    return self.queryset.filter()

def sitemap(
    request,
    sitemaps,
    section=None,
    template_name="sitemap.xml",
    content_type="application/xml",
):

    req_protocol = request.scheme
    req_site = get_current_site(request)

    if section is not None:
        if section not in sitemaps:
            raise Http404("No sitemap available for section: %r" % section)
        maps = [sitemaps[section]]
    else:
        maps = sitemaps.values()
    page = request.GET.get("p", 1)

    lastmod = None
    all_sites_lastmod = True
    urls = []
    for site in maps:
        try:
            if callable(site):
                site = site()
            urls.extend(site.get_urls(page=page, site=req_site, protocol=req_protocol))
            if all_sites_lastmod:
                site_lastmod = getattr(site, "latest_lastmod", None)
                if site_lastmod is not None:
                    lastmod = _get_latest_lastmod(lastmod, site_lastmod)
                else:
                    all_sites_lastmod = False
        except EmptyPage:
            raise Http404("Page %s empty" % page)
        except PageNotAnInteger:
            raise Http404("No page '%s'" % page)
    # If lastmod is defined for all sites, set header so as
    # ConditionalGetMiddleware is able to send 304 NOT MODIFIED
    if all_sites_lastmod:
        headers = {"Last-Modified": http_date(lastmod.timestamp())} if lastmod else None
    else:
        headers = None
    return TemplateResponse(
        request,
        template_name,
        {"urlset": urls},
        content_type=content_type,
        headers=headers,
    )

def _items(self):
    if self.i18n:
        # Create (item, lang_code) tuples for all items and languages.
        # This is necessary to paginate with all languages already considered.
        items = [
            (item, lang_code)
            for lang_code in self._languages()
            for item in self.items()
        ]
        return items
    return self.items()

def _get(self, name, item, default=None):
    try:
        attr = getattr(self, name)
    except AttributeError:
        return default
    if callable(attr):
        if self.i18n:
            # Split the (item, lang_code) tuples again for the location,
            # priority, lastmod and changefreq method calls.
            item, lang_code = item
        return attr(item)
    return attr

def _location(self, item, force_lang_code=None):
    if self.i18n:
        obj, lang_code = item
        # Activate language from item-tuple or forced one before calling location.
        with translation.override(force_lang_code or lang_code):
            return self._get("location", item)
    return self._get("location", item)

def format_coord(self, x, y):
    """Return a format string formatting the *x*, *y* coordinates."""
    return "x={} y={}".format(
        "???" if x is None else self.format_xdata(x),
        "???" if y is None else self.format_ydata(y),
    )

def inverse(self, value):
    if not self.scaled():
        raise ValueError("Not invertible until both vmin and vmax are set")
    (vmin,), _ = self.process_value(self.vmin)
    (vmax,), _ = self.process_value(self.vmax)

    if np.iterable(value):
        val = np.ma.asarray(value)
        return vmin + val * (vmax - vmin)
    else:
        return vmin + value * (vmax - vmin)

def iter_user_libraries():
    for stylelib_path in USER_LIBRARY_PATHS:
        stylelib_path = os.path.expanduser(stylelib_path)
        if os.path.exists(stylelib_path) and os.path.isdir(stylelib_path):
            yield stylelib_path

def update_user_library(library):
    """Update style library with user-defined rc files."""
    for stylelib_path in map(os.path.expanduser, USER_LIBRARY_PATHS):
        styles = read_style_directory(stylelib_path)
        update_nested_dict(library, styles)
    return library

def read_style_directory(style_dir):
    """Return dictionary of styles defined in *style_dir*."""
    styles = dict()
    for path in Path(style_dir).glob(f"*.{STYLE_EXTENSION}"):
        with warnings.catch_warnings(record=True) as warns:
            styles[path.stem] = rc_params_from_file(
                path, use_default_template=False)
        for w in warns:
            _log.warning('In %s: %s', path, w.message)
    return styles

def _remove_blacklisted_style_params(d, warn=True):
    o = {}
    for key in d:  # prevent triggering RcParams.__getitem__('backend')
        if key in STYLE_BLACKLIST:
            if warn:
                _api.warn_external(
                    f"Style includes a parameter, {key!r}, that is not "
                    "related to style.  Ignoring this parameter.")
        else:
            o[key] = d[key]
    return o

def _inverse_boundaries(self, x):
    # invert the above...
    b = self._boundaries
    return np.interp(x, np.linspace(0, 1, len(b)), b)

def inverse(self, value):
    if not self.scaled():
        raise ValueError("Not invertible until both vmin and vmax are set")
    (vmin,), _ = self.process_value(self.vmin)
    (vmax,), _ = self.process_value(self.vmax)

    if np.iterable(value):
        val = np.ma.asarray(value)
        return vmin + val * (vmax - vmin)
    else:
        return vmin + value * (vmax - vmin)

def autoscale_None(self, A):
    """If vmin or vmax are not set, use the min/max of *A* to set them."""
    A = np.asanyarray(A)
    if self.vmin is None and A.size:
        self.vmin = A.min()
    if self.vmax is None and A.size:
        self.vmax = A.max()

def register(self, app: "Flask", options: dict) -> None:
    """Called by :meth:`Flask.register_blueprint` to register all
    views and callbacks registered on the blueprint with the
    application. Creates a :class:`.BlueprintSetupState` and calls
    each :meth:`record` callbackwith it.

    :param app: The application this blueprint is being registered
        with.
    :param options: Keyword arguments forwarded from
        :meth:`~Flask.register_blueprint`.
    :param first_registration: Whether this is the first time this
        blueprint has been registered on the application.
    """
    first_registration = False

    if self.name in app.blueprints:
        assert app.blueprints[self.name] is self, (
            "A name collision occurred between blueprints"
            f" {self!r} and {app.blueprints[self.name]!r}."
            f" Both share the same name {self.name!r}."
            f" Blueprints that are created on the fly need unique"
            f" names."
        )
    else:
        app.blueprints[self.name] = self
        first_registration = True

    self._got_registered_once = True
    state = self.make_setup_state(app, options, first_registration)

    if self.has_static_folder:
        state.add_url_rule(
            f"{self.static_url_path}/<path:filename>",
            view_func=self.send_static_file,
            endpoint="static",
        )

    # Merge blueprint data into parent.
    if first_registration:

        def extend(bp_dict, parent_dict):
            for key, values in bp_dict.items():
                key = self.name if key is None else f"{self.name}.{key}"

                parent_dict[key].extend(values)

        for key, value in self.error_handler_spec.items():
            key = self.name if key is None else f"{self.name}.{key}"
            value = defaultdict(
                dict,
                {
                    code: {
                        exc_class: func for exc_class, func in code_values.items()
                    }
                    for code, code_values in value.items()
                },
            )
            app.error_handler_spec[key] = value

        for endpoint, func in self.view_functions.items():
            app.view_functions[endpoint] = func

        extend(self.before_request_funcs, app.before_request_funcs)
        extend(self.after_request_funcs, app.after_request_funcs)
        extend(
            self.teardown_request_funcs,
            app.teardown_request_funcs,
        )
        extend(self.url_default_functions, app.url_default_functions)
        extend(self.url_value_preprocessors, app.url_value_preprocessors)
        extend(self.template_context_processors, app.template_context_processors)

    for deferred in self.deferred_functions:
        deferred(state)

    cli_resolved_group = options.get("cli_group", self.cli_group)

    if self.cli.commands:
        if cli_resolved_group is None:
            app.cli.commands.update(self.cli.commands)
        elif cli_resolved_group is _sentinel:
            self.cli.name = self.name
            app.cli.add_command(self.cli)
        else:
            self.cli.name = cli_resolved_group
            app.cli.add_command(self.cli)

    for blueprint, bp_options in self._blueprints:
        url_prefix = options.get("url_prefix", "")
        if "url_prefix" in bp_options:
            url_prefix = (
                url_prefix.rstrip("/") + "/" + bp_options["url_prefix"].lstrip("/")
            )

        bp_options["url_prefix"] = url_prefix
        bp_options["name_prefix"] = options.get("name_prefix", "") + self.name + "."
        blueprint.register(app, bp_options)

def make_setup_state(
    self, app: "Flask", options: dict, first_registration: bool = False
) -> BlueprintSetupState:
    """Creates an instance of :meth:`~flask.blueprints.BlueprintSetupState`
    object that is later passed to the register callback functions.
    Subclasses can override this to return a subclass of the setup state.
    """
    return BlueprintSetupState(self, app, options, first_registration)

def add_url_rule(
    self,
    rule: str,
    endpoint: t.Optional[str] = None,
    view_func: t.Optional[t.Callable] = None,
    provide_automatic_options: t.Optional[bool] = None,
    **options: t.Any,
) -> None:
    if endpoint is None:
        endpoint = _endpoint_from_view_func(view_func)  # type: ignore
    options["endpoint"] = endpoint
    methods = options.pop("methods", None)

    # if the methods are not given and the view_func object knows its
    # methods we can use that instead.  If neither exists, we go with
    # a tuple of only ``GET`` as default.
    if methods is None:
        methods = getattr(view_func, "methods", None) or ("GET",)
    if isinstance(methods, str):
        raise TypeError(
            "Allowed methods must be a list of strings, for"
            ' example: @app.route(..., methods=["POST"])'
        )
    methods = {item.upper() for item in methods}

    # Methods that should always be added
    required_methods = set(getattr(view_func, "required_methods", ()))

    # starting with Flask 0.8 the view_func object can disable and
    # force-enable the automatic options handling.
    if provide_automatic_options is None:
        provide_automatic_options = getattr(
            view_func, "provide_automatic_options", None
        )

    if provide_automatic_options is None:
        if "OPTIONS" not in methods:
            provide_automatic_options = True
            required_methods.add("OPTIONS")
        else:
            provide_automatic_options = False

    # Add the required methods now.
    methods |= required_methods

    rule = self.url_rule_class(rule, methods=methods, **options)
    rule.provide_automatic_options = provide_automatic_options  # type: ignore

    self.url_map.add(rule)
    if view_func is not None:
        old_func = self.view_functions.get(endpoint)
        if old_func is not None and old_func != view_func:
            raise AssertionError(
                "View function mapping is overwriting an existing"
                f" endpoint function: {endpoint}"
            )
        self.view_functions[endpoint] = view_func

def format_option_help(self, formatter=None):
    if formatter is None:
        formatter = self.formatter
    outputlevel = getattr(formatter, "output_level", 0)
    formatter.store_option_strings(self)
    result = [formatter.format_heading("Options")]
    formatter.indent()
    if self.option_list:
        result.append(optparse.OptionContainer.format_option_help(self, formatter))
        result.append("\n")
    for group in self.option_groups:
        if group.level <= outputlevel and (
            group.description or _level_options(group, outputlevel)
        ):
            result.append(group.format_help(formatter))
            result.append("\n")
    formatter.dedent()
    # Drop the last "\n", or the header if no options or option groups:
    return "".join(result[:-1])

def __init__(self, options: list[str], *args: object) -> None:
    self.options = options
    super().__init__(*args)

def run_pylint(argv: Sequence[str] | None = None) -> None:
    """Run pylint.

    argv can be a sequence of strings normally supplied as arguments on the command line
    """
    from pylint.lint import Run as PylintRun

    try:
        PylintRun(argv or sys.argv[1:])
    except KeyboardInterrupt:
        sys.exit(1)

def options_by_section(
    self,
) -> Iterator[
    tuple[str, list[tuple[str, OptionDict, Any]]]
    | tuple[None, dict[str, list[tuple[str, OptionDict, Any]]]]
]:  # pragma: no cover
    """DEPRECATED: Return an iterator on options grouped by section.

    (section, [list of (optname, optdict, optvalue)])
    """
    warnings.warn(
        "options_by_section has been deprecated. It will be removed "
        "in a future release.",
        DeprecationWarning,
    )
    sections: dict[str, list[tuple[str, OptionDict, Any]]] = {}
    for optname, optdict in self.options:
        with warnings.catch_warnings():
            warnings.filterwarnings("ignore", category=DeprecationWarning)
            sections.setdefault(optdict.get("group"), []).append(  # type: ignore[arg-type]
                (optname, optdict, self.option_value(optname))
            )
    if None in sections:
        yield None, sections.pop(None)  # type: ignore[call-overload]
    for section, options in sorted(sections.items()):
        yield section.upper(), options

def options_and_values(
