    if any(i < 0 for i in args):
        raise ValueError('negative integers are not allowed in a cycle.')
    if has_dups(args):
        raise ValueError('All elements must be unique in a cycle.')
    for i in range(-len(args), 0):
        self[args[i]] = args[i + 1]

