def doprint(self, expr):
    """Internal method, don't use directly.

    Takes an expression, looks up the correct method to print it and calls
    that.
    """
    if isinstance(expr, Basic):
        method = '_print_%s' % expr.__class__.__name__
        if hasattr(self, method):
            return getattr(self, method)(expr)
        else:
            return self._print(expr)
    elif isinstance(expr, (list, tuple, Tuple)):
        l = []
        for o in expr:
            l.append(self._print(o))
        return self._print_seq(l)
    elif isinstance(expr, dict):
        items = sorted(expr.items(), key=lambda k: k[0])
        l = []
        for o, v in items:
            l.append(self._print(o) + ': ' + self._print(v))
        return self._print_dict(l)
    elif isinstance(expr, set):
