    name = "monomial_pow"
    template = dedent("""\
    def %(name)s(A, k):
        (%(A)s,) = A
        return (%(Ak)s,)
    """)
    A = self._vars("a")
    Ak = [ "%s*k" % a for a in A ]
    code = template % dict(name=name, A=", ".join(A), Ak=", ".join(Ak))
    return self._build(code, name)

