def qapply_Mul(e, **options):

    ip_doit = options.get('ip_doit', True)

    args = list(e.args)

    # If we only have 0 or 1 args, we have nothing to do and return.
    if len(args) <= 1 or not isinstance(e, Mul):
        return e
    rhs = args.pop()
    lhs = args.pop()

    # Make sure we have two non-commutative objects before proceeding.
    if (not isinstance(rhs, Wavefunction) and sympify(rhs).is_commutative) or \
            (not isinstance(lhs, Wavefunction) and sympify(lhs).is_commutative):
        return e

    # For a Pow with an integer exponent, apply one of them and reduce the
    # exponent by one.
    if isinstance(lhs, Pow) and lhs.exp.is_Integer:
        args.append(lhs.base**(lhs.exp - 1))
        lhs = lhs.base

    # Pull OuterProduct apart
    if isinstance(lhs, OuterProduct):
        args.append(lhs.ket)
        lhs = lhs.bra

    # Call .doit() on Commutator/AntiCommutator.
    if isinstance(lhs, (Commutator, AntiCommutator)):
        comm = lhs.doit()
        if isinstance(comm, Add):
            return qapply(
                e.func(*(args + [comm.args[0], rhs])) +
                e.func(*(args + [comm.args[1], rhs])),
                **options
            )
        else:
            return qapply(e.func(*args)*comm*rhs, **options)

    # Apply tensor products of operators to states
    if isinstance(lhs, TensorProduct) and all(isinstance(arg, (Operator, State, Mul, Pow)) or arg == 1 for arg in lhs.args) and \
            isinstance(rhs, TensorProduct) and all(isinstance(arg, (Operator, State, Mul, Pow)) or arg == 1 for arg in rhs.args) and \
            len(lhs.args) == len(rhs.args):
        result = TensorProduct(*[qapply(lhs.args[n]*rhs.args[n], **options) for n in range(len(lhs.args))]).expand(tensorproduct=True)
        return qapply_Mul(e.func(*args), **options)*result

    # Now try to actually apply the operator and build an inner product.
    try:
        result = lhs._apply_operator(rhs, **options)
    except (NotImplementedError, AttributeError):
        try:
            result = rhs._apply_operator(lhs, **options)
        except (NotImplementedError, AttributeError):
            if isinstance(lhs, BraBase) and isinstance(rhs, KetBase):
                result = InnerProduct(lhs, rhs)
                if ip_doit:
                    result = result.doit()
            else:
                result = None

    # TODO: I may need to expand before returning the final result.
    if result == 0:
        return S.Zero
    elif result is None:
        if len(args) == 0:
            # We had two args to begin with so args=[].
            return e
        else:
            return qapply_Mul(e.func(*(args + [lhs])), **options)*rhs
    elif isinstance(result, InnerProduct):
        return result*qapply_Mul(e.func(*args), **options)
    else:  # result is a scalar times a Mul, Add or TensorProduct
        return qapply(e.func(*args)*result, **options)

def _sympystr(self, printer, *args):
    length = len(self.args)
    s = ''
    for i in range(length):
        if isinstance(self.args[i], (Add, Pow, Mul)):
            s = s + '('
        s = s + printer._print(self.args[i])
        if isinstance(self.args[i], (Add, Pow, Mul)):
            s = s + ')'
        if i != length - 1:
            s = s + 'x'
    return s

def _pretty(self, printer, *args):

    if (_combined_printing and
            (all(isinstance(arg, Ket) for arg in self.args) or
             all(isinstance(arg, Bra) for arg in self.args))):

        length = len(self.args)
        pform = printer._print('', *args)
        for i in range(length):
            next_pform = printer._print('', *args)
            length_i = len(self.args[i].args)
            for j in range(length_i):
                part_pform = printer._print(self.args[i].args[j], *args)
                next_pform = prettyForm(*next_pform.right(part_pform))
                if j != length_i - 1:
                    next_pform = prettyForm(*next_pform.right(', '))

            if len(self.args[i].args) > 1:
                next_pform = prettyForm(
                    *next_pform.parens(left='{', right='}'))
            pform = prettyForm(*pform.right(next_pform))
            if i != length - 1:
                pform = prettyForm(*pform.right(',' + ' '))

        pform = prettyForm(*pform.left(self.args[0].lbracket))
        pform = prettyForm(*pform.right(self.args[0].rbracket))
        return pform

    length = len(self.args)
    pform = printer._print('', *args)
    for i in range(length):
        next_pform = printer._print(self.args[i], *args)
        if isinstance(self.args[i], (Add, Mul)):
            next_pform = prettyForm(
                *next_pform.parens(left='(', right=')')
            )
        pform = prettyForm(*pform.right(next_pform))
        if i != length - 1:
            if printer._use_unicode:
                pform = prettyForm(*pform.right('\N{N-ARY CIRCLED TIMES OPERATOR}' + ' '))
            else:
                pform = prettyForm(*pform.right('x' + ' '))
    return pform

def _latex(self, printer, *args):

    if (_combined_printing and
            (all(isinstance(arg, Ket) for arg in self.args) or
             all(isinstance(arg, Bra) for arg in self.args))):

        def _label_wrap(label, nlabels):
            return label if nlabels == 1 else r"\left\{%s\right\}" % label

        s = r", ".join([_label_wrap(arg._print_label_latex(printer, *args),
                                    len(arg.args)) for arg in self.args])

        return r"{%s%s%s}" % (self.args[0].lbracket_latex, s,
                              self.args[0].rbracket_latex)

    length = len(self.args)
    s = ''
    for i in range(length):
        if isinstance(self.args[i], (Add, Mul)):
            s = s + '\\left('
        # The extra {} brackets are needed to get matplotlib's latex
        # rendered to render this properly.
        s = s + '{' + printer._print(self.args[i], *args) + '}'
        if isinstance(self.args[i], (Add, Mul)):
            s = s + '\\right)'
        if i != length - 1:
            s = s + '\\otimes '
    return s

def _eval_trace(self, **kwargs):
    indices = kwargs.get('indices', None)
    exp = tensor_product_simp(self)

    if indices is None or len(indices) == 0:
        return Mul(*[Tr(arg).doit() for arg in exp.args])
    else:
        return Mul(*[Tr(value).doit() if idx in indices else value
                     for idx, value in enumerate(exp.args)])

def __set__(self, instance, value):
    if instance.__dict__.get(self.field.attname) != value and self.field.is_cached(instance):
        self.field.delete_cached_value(instance)
    instance.__dict__[self.field.attname] = value

def get_db_prep_save(self, value, connection):
    if value is None or (value == '' and
                         (not self.target_field.empty_strings_allowed or
                          connection.features.interprets_empty_strings_as_nulls)):
        return None
    else:
        return self.target_field.get_db_prep_save(value, connection=connection)

def __or__(self, other):
    if getattr(self, 'conditional', False) and getattr(other, 'conditional', False):
        return Q(self) | Q(other)
    raise NotImplementedError(
        "Use .bitand() and .bitor() for bitwise logical operations."
    )

def id_for_label(self, id_):
    if id_:
        id_ += '_0'
    return id_

def as_string(self):
    """Return a string of the file contents."""
    items = {
        "replaces_str": "",
        "initial_str": "",
    }

    imports = set()

    # Deconstruct operations
    operations = []
    for operation in self.migration.operations:
        operation_string, operation_imports = OperationWriter(operation).serialize()
        imports.update(operation_imports)
        operations.append(operation_string)
    items["operations"] = "\n".join(operations) + "\n" if operations else ""

    # Format dependencies and write out swappable dependencies right
    dependencies = []
    for dependency in self.migration.dependencies:
        if dependency[0] == "__setting__":
            dependencies.append("        migrations.swappable_dependency(settings.%s)," % dependency[1])
            imports.add("from django.conf import settings")
        else:
            dependencies.append("        %s," % self.serialize(dependency)[0])
    items["dependencies"] = "\n".join(dependencies) + "\n" if dependencies else ""

    # Format imports nicely, swapping imports of functions from migration files
    # for comments
    migration_imports = set()
    for line in list(imports):
        if re.match(r"^import (.*)\.\d+[^\s]*$", line):
            migration_imports.add(line.split("import")[1].strip())
            imports.remove(line)
            self.needs_manual_porting = True

    # django.db.migrations is always used, but models import may not be.
    # If models import exists, merge it with migrations import.
    if "from django.db import models" in imports:
        imports.discard("from django.db import models")
        imports.add("from django.db import migrations, models")
    else:
        imports.add("from django.db import migrations")

    # Sort imports by the package / module to be imported (the part after
    # "from" in "from ... import ..." or after "import" in "import ...").
    sorted_imports = sorted(imports, key=lambda i: i.split()[1])
    items["imports"] = "\n".join(sorted_imports) + "\n" if imports else ""
    if migration_imports:
        items["imports"] += (
            "\n\n# Functions from the following migrations need manual "
            "copying.\n# Move them and any dependencies into this file, "
            "then update the\n# RunPython operations to refer to the local "
            "versions:\n# %s"
        ) % "\n# ".join(sorted(migration_imports))
    # If there's a replaces, make a string for it
    if self.migration.replaces:
        items['replaces_str'] = "\n    replaces = %s\n" % self.serialize(self.migration.replaces)[0]
    # Hinting that goes into comment
    if self.include_header:
        items['migration_header'] = MIGRATION_HEADER_TEMPLATE % {
            'version': get_version(),
            'timestamp': now().strftime("%Y-%m-%d %H:%M"),
        }
    else:
        items['migration_header'] = ""

    if self.migration.initial:
        items['initial_str'] = "\n    initial = True\n"

    return MIGRATION_TEMPLATE % items

def serialize(self):
    attr_name, path, args, kwargs = self.value.deconstruct()
    return self.serialize_deconstructed(path, args, kwargs)

def _serialize_path(path):
    module, name = path.rsplit(".", 1)
    if module == "django.db.models":
        imports = {"from django.db import models"}
        name = "models.%s" % name
    else:
        imports = {"import %s" % module}
        name = path
    return name, imports

def _prepare_for_bulk_create(self, objs):
    for obj in objs:
        if obj.pk is None:
            # Populate new PK values.
            obj.pk = obj._meta.pk.get_pk_value_on_save(obj)
        obj._prepare_related_fields_for_save(operation_name='bulk_create')

def _fetch_all(self):
    if self._result_cache is None:
        self._result_cache = list(self._iterable_class(self))
    if self._prefetch_related_lookups and not self._prefetch_done:
        self._prefetch_related_objects()

def as_sql(self, compiler, connection):
    # Some backends (e.g. Oracle) raise an error when a subquery contains
    # unnecessary ORDER BY clause.
    if (
        self.subquery and
        not connection.features.ignores_unnecessary_order_by_in_subqueries
    ):
        self.clear_ordering(force=False)
    sql, params = self.get_compiler(connection=connection).as_sql()
    if self.subquery:
        sql = '(%s)' % sql
    return sql, params

def _validate_values_are_expressions(values, method_name):
    invalid_args = sorted(str(arg) for arg in values if not hasattr(arg, 'resolve_expression'))
    if invalid_args:
        raise TypeError(
            'QuerySet.%s() received non-expression(s): %s.' % (
                method_name,
                ', '.join(invalid_args),
            )
        )

def _not_support_combined_queries(self, operation_name):
    if self.query.combinator:
        raise NotSupportedError(
            'Calling QuerySet.%s() after %s() is not supported.'
            % (operation_name, self.query.combinator)
        )

def _check_table_uniqueness(self, **kwargs):
    if isinstance(self.remote_field.through, str) or not self.remote_field.through._meta.managed:
        return []
    registered_tables = {
        model._meta.db_table: model
        for model in self.opts.apps.get_models(include_auto_created=True)
        if model != self.remote_field.through and model._meta.managed
    }
    m2m_db_table = self.m2m_db_table()
    model = registered_tables.get(m2m_db_table)
    # The second condition allows multiple m2m relations on a model if
    # some point to a through model that proxies another through model.
    if model and model._meta.concrete_model != self.remote_field.through._meta.concrete_model:
        if model._meta.auto_created:
            def _get_field_name(model):
                for field in model._meta.auto_created._meta.many_to_many:
                    if field.remote_field.through is model:
                        return field.name
            opts = model._meta.auto_created._meta
            clashing_obj = '%s.%s' % (opts.label, _get_field_name(model))
        else:
            clashing_obj = model._meta.label
        if settings.DATABASE_ROUTERS:
            error_class, error_id = checks.Warning, 'fields.W344'
            error_hint = (
                'You have configured settings.DATABASE_ROUTERS. Verify '
                'that the table of %r is correctly routed to a separate '
                'database.' % clashing_obj
            )
        else:
            error_class, error_id = checks.Error, 'fields.E340'
            error_hint = None
        return [
            error_class(
                "The field's intermediary table '%s' clashes with the "
                "table name of '%s'." % (m2m_db_table, clashing_obj),
                obj=self,
                hint=error_hint,
                id=error_id,
            )
        ]
    return []

def _check_ignored_options(self, **kwargs):
    warnings = []

    if self.has_null_arg:
        warnings.append(
            checks.Warning(
                'null has no effect on ManyToManyField.',
                obj=self,
                id='fields.W340',
            )
        )

    if self._validators:
        warnings.append(
            checks.Warning(
                'ManyToManyField does not support validators.',
                obj=self,
                id='fields.W341',
            )
        )
    if (self.remote_field.limit_choices_to and self.remote_field.through and
            not self.remote_field.through._meta.auto_created):
        warnings.append(
            checks.Warning(
                'limit_choices_to has no effect on ManyToManyField '
                'with a through model.',
                obj=self,
                id='fields.W343',
            )
        )

    return warnings

def _get_m2m_db_table(self, opts):
    """
    Function that can be curried to provide the m2m table name for this
    relation.
    """
    if self.remote_field.through is not None:
        return self.remote_field.through._meta.db_table
    elif self.db_table:
        return self.db_table
    else:
        m2m_table_name = '%s_%s' % (utils.strip_quotes(opts.db_table), self.name)
        return utils.truncate_name(m2m_table_name, connection.ops.max_name_length())

def _get_m2m_attr(self, related, attr):
    """
    Function that can be curried to provide the source accessor or DB
    column name for the m2m table.
    """
    cache_attr = '_m2m_%s_cache' % attr
    if hasattr(self, cache_attr):
        return getattr(self, cache_attr)
    if self.remote_field.through_fields is not None:
        link_field_name = self.remote_field.through_fields[0]
    else:
        link_field_name = None
    for f in self.remote_field.through._meta.fields:
        if (f.is_relation and f.remote_field.model == related.related_model and
                (link_field_name is None or link_field_name == f.name)):
            setattr(self, cache_attr, getattr(f, attr))
            return getattr(self, cache_attr)

def _get_m2m_reverse_attr(self, related, attr):
    """
    Function that can be curried to provide the related accessor or DB
    column name for the m2m table.
    """
    cache_attr = '_m2m_reverse_%s_cache' % attr
    if hasattr(self, cache_attr):
        return getattr(self, cache_attr)
    found = False
    if self.remote_field.through_fields is not None:
        link_field_name = self.remote_field.through_fields[1]
    else:
        link_field_name = None
    for f in self.remote_field.through._meta.fields:
        if f.is_relation and f.remote_field.model == related.model:
            if link_field_name is None and related.related_model == related.model:
                # If this is an m2m-intermediate to self,
                # the first foreign key you find will be
                # the source column. Keep searching for
                # the second foreign key.
                if found:
                    setattr(self, cache_attr, getattr(f, attr))
                    break
                else:
                    found = True
            elif link_field_name is None or link_field_name == f.name:
                setattr(self, cache_attr, getattr(f, attr))
                break
    return getattr(self, cache_attr)

