def field_error(model_key, func, args, keywords):
    error_msg = (
        "The field %(field)s was declared with a lazy reference "
        "to '%(model)s', but %(model_error)s."
    )
    params = {
        'model': '.'.join(model_key),
        'field': keywords['field'],
        'model_error': app_model_error(model_key),
    }
    return Error(error_msg % params, obj=keywords['field'], id='fields.E307')

def _prepare(self, model):
    if self.order_with_respect_to:
        # The app registry will not be ready at this point, so we cannot
        # use get_field().
        query = self.order_with_respect_to
        try:
            self.order_with_respect_to = next(
                f for f in self._get_fields(reverse=False)
                if f.name == query or f.attname == query
            )
        except StopIteration:
            raise FieldDoesNotExist("%s has no field named '%s'" % (self.object_name, query))

        self.ordering = ('_order',)
        if not any(isinstance(field, OrderWrt) for field in model._meta.local_fields):
            model.add_to_class('_order', OrderWrt())
    else:
        self.order_with_respect_to = None

    if self.pk is None:
        if self.parents:
            # Promote the first parent link in lieu of adding yet another
            # field.
            field = next(iter(self.parents.values()))
            # Look for a local field with the same name as the
            # first parent link. If a local field has already been
            # created, use it instead of promoting the parent
            already_created = [fld for fld in self.local_fields if fld.name == field.name]
            if already_created:
                field = already_created[0]
            field.primary_key = True
            self.setup_pk(field)
        else:
            pk_class = self._get_default_pk_class()
            auto = pk_class(verbose_name='ID', primary_key=True, auto_created=True)
            model.add_to_class('id', auto)

def _get_default_pk_class(self):
    pk_class_path = getattr(
        self.app_config,
        'default_auto_field',
        settings.DEFAULT_AUTO_FIELD,
    )
    if self.app_config and self.app_config._is_default_auto_field_overridden:
        app_config_class = type(self.app_config)
        source = (
            f'{app_config_class.__module__}.'
            f'{app_config_class.__qualname__}.default_auto_field'
        )
    else:
        source = 'DEFAULT_AUTO_FIELD'
    if not pk_class_path:
        raise ImproperlyConfigured(f'{source} must not be empty.')
    try:
        pk_class = import_string(pk_class_path)
    except ImportError as e:
        msg = (
            f"{source} refers to the module '{pk_class_path}' that could "
            f"not be imported."
        )
        raise ImproperlyConfigured(msg) from e
    if not issubclass(pk_class, AutoField):
        raise ValueError(
            f"Primary key '{pk_class_path}' referred by {source} must "
            f"subclass AutoField."
        )
    return pk_class

def setup_pk(self, field):
    if not self.pk and field.primary_key:
        self.pk = field
        field.serialize = False

def get_field(self, field_name):
    """
    Return a field instance given the name of a forward or reverse field.
    """
    try:
        # In order to avoid premature loading of the relation tree
        # (expensive) we prefer checking if the field is a forward field.
        return self._forward_fields_map[field_name]
    except KeyError:
        # If the app registry is not ready, reverse fields are
        # unavailable, therefore we throw a FieldDoesNotExist exception.
        if not self.apps.models_ready:
            raise FieldDoesNotExist(
                "%s has no field named '%s'. The app cache isn't ready yet, "
                "so if this is an auto-created related field, it won't "
                "be available yet." % (self.object_name, field_name)
            )

    try:
        # Retrieve field instance by name from cached or just-computed
        # field map.
        return self.fields_map[field_name]
    except KeyError:
        raise FieldDoesNotExist("%s has no field named '%s'" % (self.object_name, field_name))

def as_sql(self, compiler, connection, function=None, template=None, arg_joiner=None, **extra_context):
    connection.ops.check_expression_support(self)
    sql_parts = []
    params = []
    for arg in self.source_expressions:
        try:
            arg_sql, arg_params = compiler.compile(arg)
        except EmptyResultSet:
            empty_result_set_value = getattr(arg, 'empty_result_set_value', NotImplemented)
            if empty_result_set_value is NotImplemented:
                raise
            arg_sql, arg_params = compiler.compile(Value(empty_result_set_value))
        sql_parts.append(arg_sql)
        params.extend(arg_params)
    data = {**self.extra, **extra_context}
    # Use the first supplied value in this order: the parameter to this
    # method, a value supplied in __init__()'s **extra (the value in
    # `data`), or the value defined on the class.
    if function is not None:
        data['function'] = function
    else:
        data.setdefault('function', self.function)
    template = template or data.get('template', self.template)
    arg_joiner = arg_joiner or data.get('arg_joiner', self.arg_joiner)
    data['expressions'] = data['field'] = arg_joiner.join(sql_parts)
    return template % data, params

def as_sql(self, compiler, connection):
    connection.ops.check_expression_support(self)
    val = self.value
    output_field = self._output_field_or_none
    if output_field is not None:
        if self.for_save:
            val = output_field.get_db_prep_save(val, connection=connection)
        else:
            val = output_field.get_db_prep_value(val, connection=connection)
        if hasattr(output_field, 'get_placeholder'):
            return output_field.get_placeholder(val, compiler, connection), [val]
    if val is None:
        # cx_Oracle does not always convert None to the appropriate
        # NULL type (like in case expressions using numbers), so we
        # use a literal SQL NULL
        return 'NULL', []
    return '%s', [val]

def apply_migration(self, state, migration, fake=False, fake_initial=False):
    """Run a migration forwards."""
    migration_recorded = False
    if self.progress_callback:
        self.progress_callback("apply_start", migration, fake)
    if not fake:
        if fake_initial:
            # Test to see if this is an already-applied initial migration
            applied, state = self.detect_soft_applied(state, migration)
            if applied:
                fake = True
        if not fake:
            # Alright, do it normally
            with self.connection.schema_editor(atomic=migration.atomic) as schema_editor:
                state = migration.apply(state, schema_editor)
                if not schema_editor.deferred_sql:
                    self.record_migration(migration)
                    migration_recorded = True
    if not migration_recorded:
        self.record_migration(migration)
    # Report progress
    if self.progress_callback:
        self.progress_callback("apply_success", migration, fake)
    return state

def ensure_schema(self):
    """Ensure the table exists and has the correct schema."""
    # If the table's there, that's fine - we've never changed its schema
    # in the codebase.
    if self.has_table():
        return
    # Make the table
    try:
        with self.connection.schema_editor() as editor:
            editor.create_model(self.Migration)
    except DatabaseError as exc:
        raise MigrationSchemaMissing("Unable to create the django_migrations table (%s)" % exc)

def allow_migrate(self, db, app_label, **hints):
    for router in self.routers:
        try:
            method = router.allow_migrate
        except AttributeError:
            # If the router doesn't have a method, skip to the next one.
            continue

        allow = method(db, app_label, **hints)

        if allow is not None:
            return allow
    return True

def record_migration(self, migration):
    # For replacement migrations, record individual statuses
    if migration.replaces:
        for app_label, name in migration.replaces:
            self.recorder.record_applied(app_label, name)
    else:
        self.recorder.record_applied(migration.app_label, migration.name)

def detect_soft_applied(self, project_state, migration):
    """
    Test whether a migration has been implicitly applied - that the
    tables or columns it would create exist. This is intended only for use
    on initial migrations (as it only looks for CreateModel and AddField).
    """
    def should_skip_detecting_model(migration, model):
        """
        No need to detect tables for proxy models, unmanaged models, or
        models that can't be migrated on the current database.
        """
        return (
            model._meta.proxy or not model._meta.managed or not
            router.allow_migrate(
                self.connection.alias, migration.app_label,
                model_name=model._meta.model_name,
            )
        )

    if migration.initial is None:
        # Bail if the migration isn't the first one in its app
        if any(app == migration.app_label for app, name in migration.dependencies):
            return False, project_state
    elif migration.initial is False:
        # Bail if it's NOT an initial migration
        return False, project_state

    if project_state is None:
        after_state = self.loader.project_state((migration.app_label, migration.name), at_end=True)
    else:
        after_state = migration.mutate_state(project_state)
    apps = after_state.apps
    found_create_model_migration = False
    found_add_field_migration = False
    fold_identifier_case = self.connection.features.ignores_table_name_case
    with self.connection.cursor() as cursor:
        existing_table_names = set(self.connection.introspection.table_names(cursor))
        if fold_identifier_case:
            existing_table_names = {name.casefold() for name in existing_table_names}
    # Make sure all create model and add field operations are done
    for operation in migration.operations:
        if isinstance(operation, migrations.CreateModel):
            model = apps.get_model(migration.app_label, operation.name)
            if model._meta.swapped:
                # We have to fetch the model to test with from the
                # main app cache, as it's not a direct dependency.
                model = global_apps.get_model(model._meta.swapped)
            if should_skip_detecting_model(migration, model):
                continue
            db_table = model._meta.db_table
            if fold_identifier_case:
                db_table = db_table.casefold()
            if db_table not in existing_table_names:
                return False, project_state
            found_create_model_migration = True
        elif isinstance(operation, migrations.AddField):
            model = apps.get_model(migration.app_label, operation.model_name)
            if model._meta.swapped:
                # We have to fetch the model to test with from the
                # main app cache, as it's not a direct dependency.
                model = global_apps.get_model(model._meta.swapped)
            if should_skip_detecting_model(migration, model):
                continue

            table = model._meta.db_table
            field = model._meta.get_field(operation.name)

            # Handle implicit many-to-many tables created by AddField.
            if field.many_to_many:
                through_db_table = field.remote_field.through._meta.db_table
                if fold_identifier_case:
                    through_db_table = through_db_table.casefold()
                if through_db_table not in existing_table_names:
                    return False, project_state
                else:
                    found_add_field_migration = True
                    continue
            with self.connection.cursor() as cursor:
                columns = self.connection.introspection.get_table_description(cursor, table)
            for column in columns:
                field_column = field.column
                column_name = column.name
                if fold_identifier_case:
                    column_name = column_name.casefold()
                    field_column = field_column.casefold()
                if column_name == field_column:
                    found_add_field_migration = True
                    break
            else:
                return False, project_state
    # If we get this far and we found at least one CreateModel or AddField migration,
    # the migration is considered implicitly applied.
    return (found_create_model_migration or found_add_field_migration), after_state

def applied_migrations(self):
    """
    Return a dict mapping (app_name, migration_name) to Migration instances
    for all applied migrations.
    """
    if self.has_table():
        return {(migration.app, migration.name): migration for migration in self.migration_qs}
    else:
        # If the django_migrations table doesn't exist, then no migrations
        # are applied.
        return {}

def snapshot_files(self):
    # watched_files may produce duplicate paths if globs overlap.
    seen_files = set()
    for file in self.watched_files():
        if file in seen_files:
            continue
        try:
            mtime = file.stat().st_mtime
        except OSError:
            # This is thrown when the file does not exist.
            continue
        seen_files.add(file)
        yield file, mtime

def notify_file_changed(self, path):
    results = file_changed.send(sender=self, file_path=path)
    logger.debug('%s notified as changed. Signal results: %s.', path, results)
    if not any(res[1] for res in results):
        trigger_reload(path)

def watch_for_template_changes(sender, **kwargs):
    for directory in get_template_directories():
        sender.watch_dir(directory, '**/*')

def get_template_directories():
    # Iterate through each template backend and find
    # any template_loader that has a 'get_dirs' method.
    # Collect the directories, filtering out Django templates.
    cwd = Path.cwd()
    items = set()
    for backend in engines.all():
        if not isinstance(backend, DjangoTemplates):
            continue

        items.update(cwd / to_path(dir) for dir in backend.engine.dirs)

        for loader in backend.engine.template_loaders:
            if not hasattr(loader, 'get_dirs'):
                continue
            items.update(
                cwd / to_path(directory)
                for directory in loader.get_dirs()
                if not is_django_path(directory)
            )
    return items

def template_changed(sender, file_path, **kwargs):
    for template_dir in get_template_directories():
        if template_dir in file_path.parents:
            reset_loaders()
            return True

def reset_loaders():
    for backend in engines.all():
        if not isinstance(backend, DjangoTemplates):
            continue
        for loader in backend.engine.template_loaders:
            loader.reset()

def watched_files(self, include_globs=True):
    """
    Yield all files that need to be watched, including module files and
    files within globs.
    """
    yield from iter_all_python_module_files()
    yield from self.extra_files
    if include_globs:
        for directory, patterns in self.directory_globs.items():
            for pattern in patterns:
                yield from directory.glob(pattern)

def __repr__(self):
    if self._wrapped is empty:
        repr_attr = self._setupfunc
    else:
        repr_attr = self._wrapped
    return "<%s: %r>" % (type(self).__name__, repr_attr)

def __copy__(self):
    if self._wrapped is empty:
        # If uninitialized, copy the wrapper. Use SimpleLazyObject, not
        # self.__class__, because the latter is proxied.
        return SimpleLazyObject(self._setupfunc)
    else:
        # If initialized, return a copy of the wrapped object.
        return copy.copy(self._wrapped)

def __deepcopy__(self, memo):
    if self._wrapped is empty:
        # We have to use SimpleLazyObject, not self.__class__, because the
        # latter is proxied.
        result = SimpleLazyObject(self._setupfunc)
        memo[id(self)] = result
        return result
    return copy.deepcopy(self._wrapped, memo)

def new_method_proxy(func):
    def inner(self, *args):
        if self._wrapped is empty:
            self._setup()
        return func(self._wrapped, *args)

    return inner

def __cast(self):
    if self._delegate_bytes:
        return self.__bytes_cast()
    elif self._delegate_text:
        return self.__text_cast()
    else:
        return func(*self.__args, **self.__kw)

def process_response(self, request, response):
    # It's too late to prevent an unsafe request with a 412 response, and
    # for a HEAD request, the response body is always empty so computing
    # an accurate ETag isn't possible.
    if request.method != "GET":
        return response

    if self.needs_etag(response) and not response.has_header("ETag"):
        set_response_etag(response)

    etag = response.get("ETag")
    last_modified = response.get("Last-Modified")
    last_modified = last_modified and parse_http_date_safe(last_modified)

    if etag or last_modified:
        return get_conditional_response(
            request,
            etag=etag,
            last_modified=last_modified,
            response=response,
        )

    return response

def parse_http_date_safe(date):
    """
    Same as parse_http_date, but return None if the input is invalid.
    """
    try:
        return parse_http_date(date)
    except Exception:
        pass

def parse_datetime(value):
    """Parse a string and return a datetime.datetime.

    This function supports time zone offsets. When the input contains one,
    the output uses a timezone with a fixed offset from UTC.

    Raise ValueError if the input is well formatted but not a valid datetime.
    Return None if the input isn't well formatted.
    """
    try:
        return datetime.datetime.fromisoformat(value)
    except ValueError:
        if match := datetime_re.match(value):
            kw = match.groupdict()
            kw["microsecond"] = kw["microsecond"] and kw["microsecond"].ljust(6, "0")
            tzinfo = kw.pop("tzinfo")
            if tzinfo == "Z":
                tzinfo = utc
            elif tzinfo is not None:
                offset_mins = int(tzinfo[-2:]) if len(tzinfo) > 3 else 0
                offset = 60 * int(tzinfo[1:3]) + offset_mins
                if tzinfo[0] == "-":
                    offset = -offset
                tzinfo = get_fixed_timezone(offset)
            kw = {k: int(v) for k, v in kw.items() if v is not None}
            return datetime.datetime(**kw, tzinfo=tzinfo)

def parse_date(value):
    """Parse a string and return a datetime.date.

    Raise ValueError if the input is well formatted but not a valid date.
    Return None if the input isn't well formatted.
    """
    try:
        return datetime.date.fromisoformat(value)
    except ValueError:
        if match := date_re.match(value):
            kw = {k: int(v) for k, v in match.groupdict().items()}
            return datetime.date(**kw)

def parse_header_name(cls, header):
    if header.startswith(cls.HTTP_PREFIX):
        header = header[len(cls.HTTP_PREFIX) :]
    elif header not in cls.UNPREFIXED_HEADERS:
        return None
    return header.replace("_", "-").title()

def urlencode(query, doseq=False):
    """
    A version of Python's urllib.parse.urlencode() function that can operate on
    MultiValueDict and non-string values.
    """
    if isinstance(query, MultiValueDict):
        query = query.lists()
    elif hasattr(query, "items"):
        query = query.items()
    query_params = []
    for key, value in query:
        if value is None:
            raise TypeError(
                "Cannot encode None for key '%s' in a query string. Did you "
                "mean to pass an empty string or omit the value?" % key
            )
        elif not doseq or isinstance(value, (str, bytes)):
            query_val = value
        else:
            try:
                itr = iter(value)
            except TypeError:
                query_val = value
            else:
                # Consume generators and iterators, when doseq=True, to
                # work around https://bugs.python.org/issue31706.
                query_val = []
                for item in itr:
                    if item is None:
                        raise TypeError(
                            "Cannot encode None for key '%s' in a query "
                            "string. Did you mean to pass an empty string or "
                            "omit the value?" % key
                        )
                    elif not isinstance(item, bytes):
                        item = str(item)
                    query_val.append(item)
        query_params.append((key, query_val))
    return original_urlencode(query_params, doseq)

def quote_etag(etag_str):
    """
    If the provided string is already a quoted ETag, return it. Otherwise, wrap
    the string in quotes, making it a strong ETag.
    """
    if ETAG_MATCH.match(etag_str):
        return etag_str
    else:
        return '"%s"' % etag_str

def rename_index(self, model, old_index, new_index):
    if self.connection.features.can_rename_index:
        self.execute(
            self._rename_index_sql(model, old_index.name, new_index.name),
            params=None,
        )
    else:
        self.remove_index(model, old_index)
        self.add_index(model, new_index)

def add_index(self, model, index):
    """Add an index on a model."""
    if (
        index.contains_expressions
        and not self.connection.features.supports_expression_indexes
    ):
        return None
    # Index.create_sql returns interpolated SQL which makes params=None a
    # necessity to avoid escaping attempts on execution.
    self.execute(index.create_sql(model, self), params=None)

def remove_index(self, model, index):
    """Remove an index from a model."""
    if (
        index.contains_expressions
        and not self.connection.features.supports_expression_indexes
    ):
        return None
    self.execute(index.remove_sql(model, self))

def add_index(self, model, index, concurrently=False):
    self.execute(
        index.create_sql(model, self, concurrently=concurrently), params=None
    )

def get_installed_libraries():
    """
    Return the built-in template tag libraries and those from installed
    applications. Libraries are stored in a dictionary where keys are the
    individual module names, not the full module paths. Example:
    django.templatetags.i18n is stored as i18n.
    """
    return {
        module_name: full_name for module_name, full_name in get_template_tag_modules()
    }

def get_package_libraries(pkg):
    """
    Recursively yield template tag libraries defined in submodules of a
    package.
    """
    for entry in walk_packages(pkg.__path__, pkg.__name__ + "."):
        try:
            module = import_module(entry[1])
        except ImportError as e:
            raise InvalidTemplateLibrary(
                "Invalid template library specified. ImportError raised when "
                "trying to load '%s': %s" % (entry[1], e)
            ) from e

        if hasattr(module, "register"):
            yield entry[1]

def get_template_libraries(self, libraries):
    loaded = {}
    for name, path in libraries.items():
        loaded[name] = import_library(path)
    return loaded

def tag(self, name=None, compile_function=None):
    if name is None and compile_function is None:
        # @register.tag()
        return self.tag_function
    elif name is not None and compile_function is None:
        if callable(name):
            # @register.tag
            return self.tag_function(name)
        else:
            # @register.tag('somename') or @register.tag(name='somename')
            def dec(func):
                return self.tag(name, func)

            return dec
    elif name is not None and compile_function is not None:
        # register.tag('somename', somefunc)
        self.tags[name] = compile_function
        return compile_function
    else:
        raise ValueError(
            "Unsupported arguments to Library.tag: (%r, %r)"
            % (name, compile_function),
        )

def filter(self, name=None, filter_func=None, **flags):
    """
    Register a callable as a template filter. Example:

    @register.filter
    def lower(value):
        return value.lower()
    """
    if name is None and filter_func is None:
        # @register.filter()
        def dec(func):
            return self.filter_function(func, **flags)

        return dec
    elif name is not None and filter_func is None:
        if callable(name):
            # @register.filter
            return self.filter_function(name, **flags)
        else:
            # @register.filter('somename') or @register.filter(name='somename')
            def dec(func):
                return self.filter(name, func, **flags)

            return dec
    elif name is not None and filter_func is not None:
        # register.filter('somename', somefunc)
        self.filters[name] = filter_func
        for attr in ("expects_localtime", "is_safe", "needs_autoescape"):
            if attr in flags:
                value = flags[attr]
                # set the flag on the filter for FilterExpression.resolve
                setattr(filter_func, attr, value)
                # set the flag on the innermost decorated function
                # for decorators that need it, e.g. stringfilter
                setattr(unwrap(filter_func), attr, value)
        filter_func._filter_name = name
        return filter_func
    else:
        raise ValueError(
            "Unsupported arguments to Library.filter: (%r, %r)"
            % (name, filter_func),
        )

def get_app_template_dirs(dirname):
    """
    Return an iterable of paths of directories to load app templates from.

    dirname is the name of the subdirectory containing templates inside
    installed applications.
    """
    template_dirs = [
        Path(app_config.path) / dirname
        for app_config in apps.get_app_configs()
        if app_config.path and (Path(app_config.path) / dirname).is_dir()
    ]
    # Immutable return value because it will be cached and shared by callers.
    return tuple(template_dirs)

def get_template_tag_modules():
    """
    Yield (module_name, module_path) pairs for all installed template tag
    libraries.
    """
    candidates = ["django.templatetags"]
    candidates.extend(
        f"{app_config.name}.templatetags" for app_config in apps.get_app_configs()
    )

    for candidate in candidates:
        try:
            pkg = import_module(candidate)
        except ImportError:
            # No templatetags package defined. This is safe to ignore.
            continue

        if hasattr(pkg, "__path__"):
            for name in get_package_libraries(pkg):
                yield name[len(candidate) + 1 :], name

def get_template(self, template_name):
    try:
        return Template(self.engine.get_template(template_name), self)
    except TemplateDoesNotExist as exc:
        reraise(exc, self)

def concrete_fields(self):
    """
    Return a list of all concrete fields on the model and its parents.

    Private API intended only to be used by Django itself; get_fields()
    combined with filtering of field properties is the public API for
    obtaining this field list.
    """
    return make_immutable_fields_list(
        "concrete_fields", (f for f in self.fields if f.concrete)
    )

def get_field(self, field_name):
    """
    Return a field instance given the name of a forward or reverse field.
    """
    try:
        # In order to avoid premature loading of the relation tree
        # (expensive) we prefer checking if the field is a forward field.
        return self._forward_fields_map[field_name]
    except KeyError:
        # If the app registry is not ready, reverse fields are
        # unavailable, therefore we throw a FieldDoesNotExist exception.
        if not self.apps.models_ready:
            raise FieldDoesNotExist(
                "%s has no field named '%s'. The app cache isn't ready yet, "
                "so if this is an auto-created related field, it won't "
                "be available yet." % (self.object_name, field_name)
            )

    try:
        # Retrieve field instance by name from cached or just-computed
        # field map.
        return self.fields_map[field_name]
    except KeyError:
        raise FieldDoesNotExist(
            "%s has no field named '%s'" % (self.object_name, field_name)
        )

def _fetch_all(self):
    if self._result_cache is None:
        self._result_cache = list(self._iterable_class(self))
    if self._prefetch_related_lookups and not self._prefetch_done:
        self._prefetch_related_objects()

def _iterator(self, use_chunked_fetch, chunk_size):
    iterable = self._iterable_class(
        self,
        chunked_fetch=use_chunked_fetch,
        chunk_size=chunk_size or 2000,
    )
    if not self._prefetch_related_lookups or chunk_size is None:
        yield from iterable
        return

    iterator = iter(iterable)
    while results := list(islice(iterator, chunk_size)):
        prefetch_related_objects(results, *self._prefetch_related_lookups)
        yield from results

def select_related(self, *fields):
    """
    Return a new QuerySet instance that will select related objects.

    If fields are specified, they must be ForeignKey fields and only those
    related objects are included in the selection.

    If select_related(None) is called, clear the list.
    """
    self._not_support_combined_queries("select_related")
    if self._fields is not None:
        raise TypeError(
            "Cannot call select_related() after .values() or .values_list()"
        )

    obj = self._chain()
    if fields == (None,):
        obj.query.select_related = False
    elif fields:
        obj.query.add_select_related(fields)
    else:
        obj.query.select_related = True
    return obj

def get_initial_alias(self):
    """
    Return the first alias for this query, after increasing its reference
    count.
    """
    if self.alias_map:
        alias = self.base_table
        self.ref_alias(alias)
    elif self.model:
        alias = self.join(self.base_table_class(self.get_meta().db_table, None))
    else:
        alias = None
    return alias

def alter_model_options(self, app_label, model_name, options, option_keys=None):
    model_state = self.models[app_label, model_name]
    model_state.options = {**model_state.options, **options}
    if option_keys:
        for key in option_keys:
            if key not in options:
                model_state.options.pop(key, False)
    self.reload_model(app_label, model_name, delay=True)

def generate_altered_options(self):
    """
    Work out if any non-schema-affecting options have changed and make an
    operation to represent them in state changes (in case Python code in
    migrations needs them).
    """
    models_to_check = self.kept_model_keys.union(
        self.kept_proxy_keys,
        self.kept_unmanaged_keys,
        # unmanaged converted to managed
        self.old_unmanaged_keys & self.new_model_keys,
        # managed converted to unmanaged
        self.old_model_keys & self.new_unmanaged_keys,
    )

    for app_label, model_name in sorted(models_to_check):
        old_model_name = self.renamed_models.get(
            (app_label, model_name), model_name
        )
        old_model_state = self.from_state.models[app_label, old_model_name]
        new_model_state = self.to_state.models[app_label, model_name]
        old_options = {
            key: value
            for key, value in old_model_state.options.items()
            if key in AlterModelOptions.ALTER_OPTION_KEYS
        }
        new_options = {
            key: value
            for key, value in new_model_state.options.items()
            if key in AlterModelOptions.ALTER_OPTION_KEYS
        }
        if old_options != new_options:
            self.add_operation(
                app_label,
                operations.AlterModelOptions(
                    name=model_name,
                    options=new_options,
                ),
            )

def __init__(self, name, options):
    self.options = options
    super().__init__(name)

def _prepare_field_lists(self):
    """
    Prepare field lists and a list of the fields that used through models
    in the old state so dependencies can be made from the through model
    deletion to the field that uses it.
    """
    self.kept_model_keys = self.old_model_keys & self.new_model_keys
    self.kept_proxy_keys = self.old_proxy_keys & self.new_proxy_keys
    self.kept_unmanaged_keys = self.old_unmanaged_keys & self.new_unmanaged_keys
    self.through_users = {}
    self.old_field_keys = {
        (app_label, model_name, field_name)
        for app_label, model_name in self.kept_model_keys
        for field_name in self.from_state.models[
            app_label, self.renamed_models.get((app_label, model_name), model_name)
        ].fields
    }
    self.new_field_keys = {
        (app_label, model_name, field_name)
        for app_label, model_name in self.kept_model_keys
        for field_name in self.to_state.models[app_label, model_name].fields
    }

def _generate_through_model_map(self):
    """Through model map generation."""
    for app_label, model_name in sorted(self.old_model_keys):
        old_model_name = self.renamed_models.get(
            (app_label, model_name), model_name
        )
        old_model_state = self.from_state.models[app_label, old_model_name]
        for field_name, field in old_model_state.fields.items():
            if hasattr(field, "remote_field") and getattr(
                field.remote_field, "through", None
            ):
                through_key = resolve_relation(
                    field.remote_field.through, app_label, model_name
                )
                self.through_users[through_key] = (
                    app_label,
                    old_model_name,
                    field_name,
                )

def _get_altered_foo_together_operations(self, option_name):
    for app_label, model_name in sorted(self.kept_model_keys):
        old_model_name = self.renamed_models.get(
            (app_label, model_name), model_name
        )
        old_model_state = self.from_state.models[app_label, old_model_name]
        new_model_state = self.to_state.models[app_label, model_name]

        # We run the old version through the field renames to account for those
        old_value = old_model_state.options.get(option_name)
        old_value = (
            {
                tuple(
                    self.renamed_fields.get((app_label, model_name, n), n)
                    for n in unique
                )
                for unique in old_value
            }
            if old_value
            else set()
        )

        new_value = new_model_state.options.get(option_name)
        new_value = set(new_value) if new_value else set()

        if old_value != new_value:
            dependencies = []
            for foo_togethers in new_value:
                for field_name in foo_togethers:
                    field = new_model_state.get_field(field_name)
                    if field.remote_field and field.remote_field.model:
                        dependencies.extend(
                            self._get_dependencies_for_foreign_key(
                                app_label,
                                model_name,
                                field,
                                self.to_state,
                            )
                        )
            yield (
                old_value,
                new_value,
                app_label,
                model_name,
                dependencies,
            )

def _get_dependencies_for_foreign_key(app_label, model_name, field, project_state):
    remote_field_model = None
    if hasattr(field.remote_field, "model"):
        remote_field_model = field.remote_field.model
    else:
        relations = project_state.relations[app_label, model_name]
        for (remote_app_label, remote_model_name), fields in relations.items():
            if any(
                field == related_field.remote_field
                for related_field in fields.values()
            ):
                remote_field_model = f"{remote_app_label}.{remote_model_name}"
                break
    # Account for FKs to swappable models
    swappable_setting = getattr(field, "swappable_setting", None)
    if swappable_setting is not None:
        dep_app_label = "__setting__"
        dep_object_name = swappable_setting
    else:
        dep_app_label, dep_object_name = resolve_relation(
            remote_field_model,
            app_label,
            model_name,
        )
    dependencies = [(dep_app_label, dep_object_name, None, True)]
    if getattr(field.remote_field, "through", None):
        through_app_label, through_object_name = resolve_relation(
            remote_field_model,
            app_label,
            model_name,
        )
        dependencies.append((through_app_label, through_object_name, None, True))
    return dependencies

def render(self, context):
    "Display stage -- can be called many times"
    with context.render_context.push_state(self):
        if context.template is None:
            with context.bind_template(self):
                context.template_name = self.name
                return self._render(context)
        else:
            return self._render(context)

def render(self, context):
    from django.urls import NoReverseMatch, reverse

    args = [arg.resolve(context) for arg in self.args]
    kwargs = {k: v.resolve(context) for k, v in self.kwargs.items()}
    view_name = self.view_name.resolve(context)
    try:
        current_app = context.request.current_app
    except AttributeError:
        try:
            current_app = context.request.resolver_match.namespace
        except AttributeError:
            current_app = None
    # Try to look up the URL. If it fails, raise NoReverseMatch unless the
    # {% url ... as var %} construct is used, in which case return nothing.
    url = ""
    try:
        url = reverse(view_name, args=args, kwargs=kwargs, current_app=current_app)
    except NoReverseMatch:
        if self.asvar is None:
            raise

    if self.asvar:
        context[self.asvar] = url
        return ""
    else:
        if context.autoescape:
            url = conditional_escape(url)
        return url

def all_valid(formsets):
